// IsAccessibleMode returns true if accessibility mode should be enabled.
// This checks the ACCESSIBLE environment variable.
// Set ACCESSIBLE=1 (or any non-empty value) to enable accessible mode,
// which uses simpler prompts that work better with screen readers.
func IsAccessibleMode() bool {
	return os.Getenv("ACCESSIBLE") != ""
}

// entireTheme returns the Dracula theme for consistent styling.
func entireTheme() *huh.Theme {
	return huh.ThemeDracula()
}

// NewAccessibleForm creates a new huh form with accessibility mode
// enabled if the ACCESSIBLE environment variable is set.
// Note: WithAccessible() is only available on forms, not individual fields.
// Always wrap confirmations and other prompts in a form to enable accessibility.
func NewAccessibleForm(groups ...*huh.Group) *huh.Form {
	form := huh.NewForm(groups...).WithTheme(entireTheme())
	if IsAccessibleMode() {
		form = form.WithAccessible(true)
	}
	return form
}

// handleFormCancellation handles cancellation from huh form prompts.
// User abort (Ctrl+C) and timeout both print a cancelled message and return nil.
// Other errors are wrapped with the action name for context.
func handleFormCancellation(w io.Writer, action string, err error) error {
	if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, huh.ErrTimeout) {
		fmt.Fprintf(w, "%s cancelled.\n", action)
		return nil
	}
	return fmt.Errorf("%s prompt failed: %w", action, err)
}

// printSessionCommand writes a single session resume command line to w.
// It appends a "(most recent)" label to the last entry in a multi-session list,
// and a "# prompt" comment when a prompt is available.
func printSessionCommand(w io.Writer, resumeCmd, prompt string, isMulti, isLast bool) {
	comment := ""
	if isMulti && isLast {
		if prompt != "" {
			comment = fmt.Sprintf("  # %s (most recent)", prompt)
		} else {
			comment = "  # (most recent)"
		}
	} else if prompt != "" {
		comment = "  # " + prompt
	}
	fmt.Fprintf(w, "  %s%s\n", resumeCmd, comment)
}

// fileExists checks if a file exists
func fileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

// copyFile copies a file from src to dst using os.Root for traversal-resistant
// writes (Go 1.24+). dst must be absolute and reside under either the repo
// worktree root, the user's home directory (for agent session dirs such as
// ~/.claude/), or the system temp directory (used during tests).
// The kernel enforces that the write cannot escape the allowed directory,
// eliminating TOCTOU races and symlink escapes.
func copyFile(src, dst string) error {
	src = filepath.Clean(src)
	dst = filepath.Clean(dst)

	if !filepath.IsAbs(dst) {
		return fmt.Errorf("copyFile: dst must be absolute, got %q", dst)
	}

	input, err := os.ReadFile(src)
	if err != nil {
		return err //nolint:wrapcheck // already present in codebase
	}

	root, relPath, err := openAllowedRoot(dst)
	if err != nil {
		return err
	}
	defer root.Close()

	if err := osroot.WriteFile(root, relPath, input, 0o600); err != nil {
		return fmt.Errorf("failed to write file: %w", err)
	}
	return nil
}

// openAllowedRoot finds the allowed root directory that contains dst and returns
// an os.Root handle along with the relative path within that root.
// Allowed directories: repo worktree root, user home, system temp dir.
// dst is resolved through symlinks before matching to handle macOS /var → /private/var.
func openAllowedRoot(dst string) (*os.Root, string, error) {
	allowed := allowedRootDirs()

	// Resolve the directory portion of dst through symlinks so that e.g.
	// /var/folders/... matches /private/var/folders/... on macOS.
	// Only the parent directory is resolved; the final component may not exist yet.
	resolvedDst := dst
	if r, err := filepath.EvalSymlinks(filepath.Dir(dst)); err == nil {
		resolvedDst = filepath.Join(r, filepath.Base(dst))
	}

	for _, dir := range allowed {
		if !paths.IsSubpath(dir, resolvedDst) {
			continue
		}
		rel, err := filepath.Rel(dir, resolvedDst)
		if err != nil {
			continue
		}
		root, err := os.OpenRoot(dir)
		if err != nil {
			return nil, "", fmt.Errorf("openAllowedRoot: failed to open root %q: %w", dir, err)
		}
		return root, rel, nil
	}

	return nil, "", fmt.Errorf("openAllowedRoot: dst %q is outside allowed directories", dst)
}

// allowedRootDirs returns the list of directories that copyFile may write to.
// Directories are resolved through symlinks so they match resolved dst paths.
func allowedRootDirs() []string {
	allowed := make([]string, 0, 3)

	if repoRoot, err := paths.WorktreeRoot(context.Background()); err == nil {
		allowed = appendResolved(allowed, repoRoot)
	}
	if home, err := os.UserHomeDir(); err == nil {
		allowed = appendResolved(allowed, home)
	}
	if tmpDir := os.TempDir(); tmpDir != "" {
		allowed = appendResolved(allowed, tmpDir)
	}

	return allowed
}

// appendResolved appends dir to the list after resolving symlinks.
// Falls back to the original path if symlink resolution fails.
func appendResolved(dirs []string, dir string) []string {
	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
		return append(dirs, resolved)
	}
	return append(dirs, dir)
}

package summarize

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
)

// summarizationPromptTemplate is the prompt used to generate summaries via the Claude CLI.
//
// Security note: The transcript is wrapped in <transcript> tags to provide clear boundary
// markers. This helps contain any potentially malicious content within the transcript
// (e.g., prompt injection attempts in user messages or file contents) by giving the LLM
// a clear structural signal about where the untrusted content begins and ends.
const summarizationPromptTemplate = `Analyze this development session transcript and generate a structured summary.

<transcript>
%s
</transcript>

Return a JSON object with this exact structure:
{
  "intent": "What the user was trying to accomplish (1-2 sentences)",
  "outcome": "What was actually achieved (1-2 sentences)",
  "learnings": {
    "repo": ["Codebase-specific patterns, conventions, or gotchas discovered"],
    "code": [{"path": "file/path.go", "line": 42, "end_line": 56, "finding": "What was learned"}],
    "workflow": ["General development practices or tool usage insights"]
  },
  "friction": ["Problems, blockers, or annoyances encountered"],
  "open_items": ["Tech debt, unfinished work, or things to revisit later"]
}

Guidelines:
- Be concise but specific
- Include line numbers for code learnings when the transcript references specific lines
- Friction should capture both blockers and minor annoyances
- Open items are things intentionally deferred, not failures
- Empty arrays are fine if a category doesn't apply
- Return ONLY the JSON object, no markdown formatting or explanation`

// DefaultModel is the default model used for summarization.
// Sonnet provides a good balance of quality and cost, with 1M context window
// to handle long transcripts without truncation.
const DefaultModel = "sonnet"

var defaultTextGeneratorFactory = func() (agent.TextGenerator, error) {
	textGenerator, ok := agent.AsTextGenerator(claudecode.NewClaudeCodeAgent())
	if !ok {
		return nil, errors.New("default summarizer does not support text generation")
	}
	return textGenerator, nil
}

// ClaudeGenerator generates summaries using the Claude CLI.
type ClaudeGenerator struct {
	// TextGenerator is the primitive used to obtain raw model output.
	// If nil, uses the built-in Claude Code text generator.
	TextGenerator agent.TextGenerator

	// Model is the Claude model to use for summarization.
	// If empty, defaults to DefaultModel ("sonnet").
	Model string
}

// Generate creates a summary from checkpoint data by calling the Claude CLI.
func (g *ClaudeGenerator) Generate(ctx context.Context, input Input) (*checkpoint.Summary, error) {
	// Format the transcript for the prompt
	transcriptText := FormatCondensedTranscript(input)

	// Build the prompt
	prompt := buildSummarizationPrompt(transcriptText)

	model := g.Model
	if model == "" {
		model = DefaultModel
	}

	textGenerator := g.TextGenerator
	if textGenerator == nil {
		var err error
		textGenerator, err = defaultTextGeneratorFactory()
		if err != nil {
			return nil, err
		}
	}

	resultJSON, err := textGenerator.GenerateText(ctx, prompt, model)
	if err != nil {
		return nil, fmt.Errorf("failed to generate summary text: %w", err)
	}

	return parseSummaryText(resultJSON)
}

// buildSummarizationPrompt creates the prompt for the Claude CLI.
func buildSummarizationPrompt(transcriptText string) string {
	return fmt.Sprintf(summarizationPromptTemplate, transcriptText)
}

func parseSummaryText(result string) (*checkpoint.Summary, error) {
	resultJSON := extractJSONFromMarkdown(result)

	var summary checkpoint.Summary
	if err := json.Unmarshal([]byte(resultJSON), &summary); err != nil {
		start := strings.Index(resultJSON, "{")
		end := strings.LastIndex(resultJSON, "}")
		if start >= 0 && end > start {
			candidate := resultJSON[start : end+1]
			if candidate != resultJSON {
				if retryErr := json.Unmarshal([]byte(candidate), &summary); retryErr == nil {
					return &summary, nil
				}
			}
		}
		return nil, fmt.Errorf("failed to parse summary JSON: %w (response: %s)", err, resultJSON)
	}

	return &summary, nil
}

// extractJSONFromMarkdown attempts to extract JSON from markdown code blocks.
// If the input is not wrapped in code blocks, it returns the input unchanged.
func extractJSONFromMarkdown(s string) string {
	s = strings.TrimSpace(s)

	// Check for ```json ... ``` blocks
	if strings.HasPrefix(s, "```json") {
		s = strings.TrimPrefix(s, "```json")
		if idx := strings.LastIndex(s, "```"); idx != -1 {
			s = s[:idx]
		}
		return strings.TrimSpace(s)
	}

	// Check for ``` ... ``` blocks
	if strings.HasPrefix(s, "```") {
		s = strings.TrimPrefix(s, "```")
		if idx := strings.LastIndex(s, "```"); idx != -1 {
			s = s[:idx]
		}
		return strings.TrimSpace(s)
	}

	return s
}

