				entries = append(entries, Entry{
					Type:    EntryTypeUser,
					Content: text,
				})
			}
		case "assistant":
			text := opencode.ExtractTextFromParts(msg.Parts)
			if text != "" {
				entries = append(entries, Entry{
					Type:    EntryTypeAssistant,
					Content: text,
				})

