package dispatch

import (
	"context"
	"errors"
)

type Mode int

const (
	ModeServer Mode = iota
	ModeLocal
)

// Options holds all parsed CLI inputs.
type Options struct {
	Mode        Mode
	RepoPaths   []string
	Org         string
	Since       string
	Until       string
	Branches    []string
	AllBranches bool
	Generate    bool
	Voice       string
	Format      string
	DryRun      bool
	Wait        bool
}

// Run is the entry point after flags are parsed.
func Run(ctx context.Context, opts Options) (*Dispatch, error) {
	if opts.Mode == ModeServer && len(opts.RepoPaths) > 0 {
		return nil, errors.New("--repos requires --local")
	}
	if opts.Mode == ModeServer {
		return runServer(ctx, opts)
	}
	return runLocal(ctx, opts)
}

package dispatch

import (
	_ "embed"
	"os"
	"strings"
)

//go:embed voices/neutral.md
var voiceNeutral string

//go:embed voices/marvin.md
var voiceMarvin string

// Voice is the resolved form of a --voice input.
type Voice struct {
	Name     string
	Text     string
	IsPreset bool
}

var presets = map[string]string{
	"neutral": voiceNeutral,
	"marvin":  voiceMarvin,
}

// ResolveVoice applies the resolution chain preset -> file -> literal.
func ResolveVoice(value string) Voice {
	if value == "" {
		return Voice{Name: "neutral", Text: voiceNeutral, IsPreset: true}
	}

	name := strings.ToLower(strings.TrimSpace(value))
	if text, ok := presets[name]; ok {
		return Voice{Name: name, Text: text, IsPreset: true}
	}

	if info, err := os.Stat(value); err == nil && !info.IsDir() {
		if body, err := os.ReadFile(value); err == nil {
			return Voice{Text: string(body)}
		}
	}

	return Voice{Text: value}
}

// ListPresetNames returns the shipped preset names in stable order.
func ListPresetNames() []string {
	return []string{"neutral", "marvin"}
}

