  const repoOptions = useRepoBreadcrumbOptions(org)
  const { isPublicRepo } = useRepoLinkBehavior(`${org}/${repo}`)

  const handleBranchChange = (newBranch: string | null) => {
    if (!newBranch) return
    navigate({
      to: "/gh/$org/$repo/checkpoints/$branch",
      params: { org, repo, branch: newBranch },
    })
  }

  const branches = branchesData?.branches ?? []
  const defaultBranch = branchesData?.default_branch ?? "main"

  // Sort branches with default branch first, then create options for Combobox
  const sortedBranches = [...branches].sort((a, b) => {
    if (a === defaultBranch) return -1
    if (b === defaultBranch) return 1
    return a.localeCompare(b)
  })

  const branchOptions: ComboboxOption[] = sortedBranches.map((b) => ({
    id: b,
    label: b,
  }))
