  useEffect(() => {
    const timer = setTimeout(() => setDebouncedQuery(searchQuery.trim()), 300)
    return () => clearTimeout(timer)
  }, [searchQuery])

  const trimmedQuery = searchQuery.trim()
  const isFilterActive = trimmedQuery.length > 0
  const isServerSearchActive = isSearchEnabled && isFilterActive
  const allCommits = useMemo(() => data?.commits ?? [], [data?.commits])

  const { data: searchData, isFetching: isSearchFetching } = useSearchCheckpointsQuery(
    org,
    repo,
    isServerSearchActive ? debouncedQuery : "",
    branch,
  )

  const isDebouncing = isServerSearchActive && trimmedQuery !== debouncedQuery
  const isSearchPending = isServerSearchActive && (isDebouncing || isSearchFetching)

  const commits = useMemo(() => {
    if (!isFilterActive) return allCommits
    const query = trimmedQuery.toLowerCase()
    const locallyMatched = allCommits.filter((commit) => {
      const commitMessage = commit.commitMessage?.toLowerCase() ?? ""
      const author = commit.commitAuthorUsername?.toLowerCase() ?? ""
      const prompts = (commit.checkpoints ?? []).map(
        (checkpoint) => checkpoint.sessions?.[0]?.prompt?.trim().toLowerCase() ?? "",
      )
      return (
        commitMessage.includes(query) ||
        author.includes(query) ||
        prompts.some((prompt) => prompt.includes(query))
      )
    })

    if (!isServerSearchActive) {
      return locallyMatched
    }

    // Wait for server results before showing anything — avoids a jarring
    // two-phase flash where local results appear first, then shift when
    // server results arrive. Also catches stale placeholderData when the
    // user has changed the query but new results haven't arrived yet.
    if (!searchData || isDebouncing || isSearchFetching) return []

    const matchedCheckpointIds = new Set(
      searchData.checkpoints.map((checkpoint) => checkpoint.checkpointId),
    )
    const scoreByCheckpointId = searchData.searchMeta ?? {}

