      ),
    )

    // Track which checkpoint IDs are already covered by allCommits
    const coveredCheckpointIds = new Set<string>()
    for (const commit of withServerMatches) {
      for (const cp of commit.checkpoints ?? []) {
        if (matchedCheckpointIds.has(cp.checkpointId)) {
          coveredCheckpointIds.add(cp.checkpointId)
        }
      }
    }

    // Synthesize commit entries for search results not in allCommits
    const syntheticCommits: CommitInfo[] = []
    for (const cp of searchData.checkpoints) {
      if (coveredCheckpointIds.has(cp.checkpointId)) continue
      syntheticCommits.push({
        commitSha: cp.commitSha,
        commitMessage: cp.commitMessage,
        commitAuthor: cp.commitAuthor,
        commitAuthorUsername: cp.commitAuthorUsername,
        commitDate: cp.commitDate,
        additions: cp.additions,
        deletions: cp.deletions,
        filesChanged: null,
        filesTouched: cp.filesTouched,
        fileStats: cp.fileStats,
        url: null,
        checkpoints: [cp],
      })
    }

    // Synthetic commits first so rich entries from allCommits overwrite them
    const combined = new Map<string, CommitInfo>()
    for (const commit of [...syntheticCommits, ...locallyMatched, ...withServerMatches]) {
