import { useEffect, useMemo, useRef, useState, type ReactNode } from "react"

import { useAuth } from "@/domains/platform/auth"
import { usePersistentState } from "@/hooks/usePersistentState"

import { useSyncStatusQuery } from "../repositories/hooks/useRepositoriesQuery"
import { Sidebar } from "./Sidebar"
import { AppLayoutContext, MobileMenuContext } from "./useMobileMenu"

interface AppLayoutProps {
  children: ReactNode
}

export function AppLayout({ children }: AppLayoutProps) {
  const { isAuthenticated } = useAuth()

  // Poll sync status to detect webhook updates and invalidate stale queries
  useSyncStatusQuery(isAuthenticated)

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false)
  const [isHovering, setIsHovering] = useState(false)

  const [isDesktopExpanded, setIsDesktopExpanded] = usePersistentState("sidebar-expanded", true)

  const [isResizing, setIsResizing] = useState(false)
  const resizeTimeoutRef = useRef<number | null>(null)
  const viewportLeaveTimeoutRef = useRef<number | null>(null)

  useEffect(() => {
    let isCurrentlyResizing = false

    const resizeObserver = new ResizeObserver(() => {
      // Only trigger state update if not already resizing
      if (!isCurrentlyResizing) {
        isCurrentlyResizing = true
        setIsResizing(true)
      }

      if (resizeTimeoutRef.current) {
        window.clearTimeout(resizeTimeoutRef.current)
      }

      resizeTimeoutRef.current = window.setTimeout(() => {
        isCurrentlyResizing = false
        setIsResizing(false)
      }, 150)
    })

    resizeObserver.observe(document.body)

    return () => {
      resizeObserver.disconnect()
      if (resizeTimeoutRef.current) {
        window.clearTimeout(resizeTimeoutRef.current)
      }
      if (viewportLeaveTimeoutRef.current) {
        window.clearTimeout(viewportLeaveTimeoutRef.current)
      }
    }
  }, [])

  // Floating state: hovering over condensed sidebar (not pinned/expanded)
  const isFloating = isHovering && !isDesktopExpanded

  // When expanded or floating, use full width
  const isDesktopWide = isDesktopExpanded || isFloating

  const sidebarClasses = [
    isResizing
      ? ""
      : "transition-transform duration-150 ease-out md:transition-[width] md:duration-150",
    "overflow-hidden fixed inset-y-0 start-0 z-overlay",
    // Desktop: always show border, floating also gets shadow
    "md:border-r md:border-subtle",
    isFloating ? "md:shadow-lg" : "",
    // Width: expanded/floating = 260px, condensed = 53px (52px + 1px border)
    isDesktopWide ? "md:w-70" : "md:w-[53px]",
    // Mobile translate
    isMobileMenuOpen ? "w-70 translate-x-0 shadow-lg" : "w-70 -translate-x-full md:translate-x-0",
  ].join(" ")

  const handleMouseEnter = () => {
    // Cancel any pending viewport leave timeout
    if (viewportLeaveTimeoutRef.current) {
      window.clearTimeout(viewportLeaveTimeoutRef.current)
      viewportLeaveTimeoutRef.current = null
    }
    if (!isDesktopExpanded) {
      setIsHovering(true)
      // Close any open dropdowns when sidebar floats
      window.dispatchEvent(new CustomEvent("sidebar-expand"))
    }
  }

  const handleMouseLeave = (event: React.MouseEvent) => {
    // Check if cursor left the viewport by examining coordinates
    // When cursor leaves the window, coordinates will be at or beyond edges
    const { clientX, clientY } = event
    const leftViewport =
      clientX <= 0 || clientY <= 0 || clientX >= window.innerWidth || clientY >= window.innerHeight

    if (leftViewport) {
      // Debounce closing when cursor leaves viewport
      viewportLeaveTimeoutRef.current = window.setTimeout(() => {
        setIsHovering(false)
        viewportLeaveTimeoutRef.current = null
      }, 800)
    } else {
      // Close immediately when cursor moves to main content
      setIsHovering(false)
    }
  }

  const mobileMenuContextValue = useMemo(
    () => ({
      openMobileMenu: () => setIsMobileMenuOpen(true),
    }),
    [],
  )

  return (
    <AppLayoutContext.Provider value={true}>
      <MobileMenuContext.Provider value={mobileMenuContextValue}>
        <aside
          className={sidebarClasses}
          role="dialog"
          aria-label="Sidebar"
          onMouseEnter={handleMouseEnter}
          onMouseLeave={handleMouseLeave}
        >
          <Sidebar
            isDesktopExpanded={isDesktopExpanded}
            isFloating={isFloating}
            isMobileMenuOpen={isMobileMenuOpen}
            onCollapseDesktop={() => {
              setIsMobileMenuOpen(false)
              setIsDesktopExpanded(false)
              setIsHovering(false)
            }}
            onExpandDesktop={() => setIsDesktopExpanded(true)}
            onFloat={handleMouseEnter}
            onCloseFloat={() => setIsHovering(false)}
            onCloseMobile={() => setIsMobileMenuOpen(false)}
          />
        </aside>

        <div
          className={`fixed inset-0 z-backdrop bg-neutral-900/60 backdrop-blur-sm transition-opacity duration-150 md:hidden ${
            isMobileMenuOpen ? "opacity-100" : "pointer-events-none opacity-0"
          }`}
          onClick={() => setIsMobileMenuOpen(false)}
        />

        <main
          className={`flex min-h-screen flex-col ease-out ${isResizing ? "" : "transition-[margin] duration-150"} ${
            isDesktopExpanded ? "md:ml-70" : "md:ml-[53px]"
          }`}
        >
          <div className="isolate flex flex-1 flex-col">{children}</div>
        </main>
      </MobileMenuContext.Provider>
    </AppLayoutContext.Provider>
  )
}

