  q?: string
  types?: string
  repo?: string
  author?: string
  date?: string
  branch?: string
  sort?: string
  page?: string
}

export const Route = createFileRoute("/_authenticated/search")({
  beforeLoad: ({ context }) => {
    // Respect dev overrides (VITE_FORCE_FLAG_SEMANTIC_SEARCH, VITE_FORCE_ALL_FLAGS)
