  validateSearch: (search: Record<string, unknown>): SearchPageParams => ({
    q: (search.q as string) || undefined,
    types: (search.types as string) || undefined,
    repo: (search.repo as string) || undefined,
    author: (search.author as string) || undefined,
    date: (search.date as string) || undefined,
    branch: (search.branch as string) || undefined,
    sort: (search.sort as string) || undefined,
    page: (search.page as string) || undefined,
  }),
})

function SearchPage() {
  const navigate = useNavigate({ from: "/search" })
  const params = Route.useSearch()
  const { recent } = useRecentSearches()

  const q = params.q ?? ""
  const pageRaw = params.page ? parseInt(params.page, 10) : 1
  const page = Number.isNaN(pageRaw) ? 1 : pageRaw
  const PAGE_SIZE = 20

  const posthog = usePostHog()
