      const clientMs = Date.now() - startTimeRef.current
      setElapsedMs(clientMs)
      startTimeRef.current = null

      if (data && q.trim()) {
        posthog.capture("search_executed", {
          query: q,
          query_length: q.length,
          source: "search_page",
          result_count: data.total,
          client_latency_ms: clientMs,
          timing_total_ms: data.timing?.total_ms ?? null,
          timing_keyword_ms: data.timing?.keyword_ms ?? null,
          timing_embedding_ms: data.timing?.embedding_ms ?? null,
