    () =>
      [...filtered].sort((a, b) => {
        if (sort === "date") {
          const aDate = a.type === "checkpoint" ? a.data.createdAt : ""
          const bDate = b.type === "checkpoint" ? b.data.createdAt : ""
          return bDate.localeCompare(aDate)
        }
        if (sort === "author") {
          const aAuthor =
            a.type === "checkpoint" ? (a.data.authorUsername ?? a.data.author) : a.data.org
          const bAuthor =
            b.type === "checkpoint" ? (b.data.authorUsername ?? b.data.author) : b.data.org
