    const map = new Map<string, number>()
    for (const r of allResults) {
      if (r.type === "checkpoint") {
        const key = `${r.data.org}/${r.data.repo}`
        map.set(key, (map.get(key) ?? 0) + 1)
      }
    }
    return [...map.entries()]
      .sort((a, b) => b[1] - a[1])
      .map(([fullName, count]) => ({ fullName, count }))
  }, [allResults])

  // Branches available for the branch filter (from checkpoint results)
  const branchesInResults = useMemo(() => {
    const map = new Map<string, number>()
    for (const r of allResults) {
      if (r.type === "checkpoint" && r.data.branch) {
        map.set(r.data.branch, (map.get(r.data.branch) ?? 0) + 1)
