import { sql, type Kysely, type Selectable } from "kysely"

import type { DB, RepoCheckpointAnalyses } from "../../../db/types"
import type { AnalysesNamespace, AnalysisRow } from "../db/db-types"
import { generateId } from "../uuid"
import { dateToStr } from "./row-helpers"

function mapAnalysisRow(row: Selectable<RepoCheckpointAnalyses>): AnalysisRow {
  return {
    id: row.id,
    repo_id: row.repo_id,
    checkpoint_id: row.checkpoint_id,
    status: row.status as "pending" | "generating" | "complete" | "failed",
    analysis_json: row.analysis_json
      ? typeof row.analysis_json === "string"
        ? row.analysis_json
        : JSON.stringify(row.analysis_json)
      : null,
    error_message: row.error_message,
    attempt_count: row.attempt_count,
    queued_at: row.queued_at.toISOString(),
    started_at: dateToStr(row.started_at),
    completed_at: dateToStr(row.completed_at),
  }
}

export function createAnalysesNamespace(db: Kysely<DB>): AnalysesNamespace {
  return {
    async getByCheckpointId(repoId, checkpointId) {
      const row = await db
        .selectFrom("repo_checkpoint_analyses")
        .selectAll()
        .where("repo_id", "=", repoId)
        .where("checkpoint_id", "=", checkpointId)
        .executeTakeFirst()

      if (!row) return null

      return mapAnalysisRow(row)
    },

    async getByCheckpointIds(repoId, checkpointIds) {
      if (checkpointIds.length === 0) return []

      const rows = await db
        .selectFrom("repo_checkpoint_analyses")
        .selectAll()
        .where("repo_id", "=", repoId)
        .where("checkpoint_id", "in", checkpointIds)
        .execute()

      return rows.map(mapAnalysisRow)
    },

    async upsertPending(repoId, checkpointId, queuedAt) {
      const now = new Date()
      const queuedDate = new Date(queuedAt)
      await db
        .insertInto("repo_checkpoint_analyses")
        .values({
          id: generateId(),
          repo_id: repoId,
          checkpoint_id: checkpointId,
          status: "pending",
          queued_at: queuedDate,
          created_at: now,
          updated_at: now,
        })
        .onDuplicateKeyUpdate({
          // Skip if already complete — prevents duplicate messages from
          // triggering regeneration loops
          status: sql`CASE WHEN status = 'complete' THEN status ELSE 'pending' END`,
          queued_at: sql`CASE WHEN status = 'complete' THEN queued_at ELSE ${queuedDate} END`,
          error_message: sql`CASE WHEN status = 'complete' THEN error_message ELSE NULL END`,
          analysis_json: sql`CASE WHEN status = 'complete' THEN analysis_json ELSE NULL END`,
          started_at: sql`CASE WHEN status = 'complete' THEN started_at ELSE NULL END`,
          completed_at: sql`CASE WHEN status = 'complete' THEN completed_at ELSE NULL END`,
          updated_at: now,
        })
        .execute()
    },

    async markGenerating(repoId, checkpointId, queuedAt) {
      const now = new Date()
      const result = await db
        .updateTable("repo_checkpoint_analyses")
        .set({
          status: "generating",
          started_at: now,
          attempt_count: sql`attempt_count + 1`,
          updated_at: now,
        })
        .where("repo_id", "=", repoId)
        .where("checkpoint_id", "=", checkpointId)
        .where("queued_at", "=", new Date(queuedAt))
        .where("status", "in", ["pending", "failed"])
        .executeTakeFirst()

      return BigInt(result.numUpdatedRows) > 0n
    },

    async markComplete(repoId, checkpointId, analysisJson, queuedAt) {
      const now = new Date()
      const result = await db
        .updateTable("repo_checkpoint_analyses")
        .set({
          status: "complete",
          analysis_json: analysisJson,
          completed_at: now,
          error_message: null,
          updated_at: now,
        })
        .where("repo_id", "=", repoId)
        .where("checkpoint_id", "=", checkpointId)
        .where("queued_at", "=", new Date(queuedAt))
        .where("status", "=", "generating")
        .executeTakeFirst()

      return BigInt(result.numUpdatedRows) > 0n
    },

    async markFailed(repoId, checkpointId, errorMessage, queuedAt) {
      const now = new Date()
      const result = await db
        .updateTable("repo_checkpoint_analyses")
        .set({
          status: "failed",
          error_message: errorMessage,
          updated_at: now,
        })
        .where("repo_id", "=", repoId)
        .where("checkpoint_id", "=", checkpointId)
        .where("queued_at", "=", new Date(queuedAt))
        .where("status", "=", "generating")
        .executeTakeFirst()

      return BigInt(result.numUpdatedRows) > 0n
    },

    async delete(repoId, checkpointId, queuedAt) {
      let query = db
        .deleteFrom("repo_checkpoint_analyses")
        .where("repo_id", "=", repoId)
        .where("checkpoint_id", "=", checkpointId)

      if (queuedAt) {
        // When scoped to a specific enqueue attempt, only delete if the row
        // is still pending — a fast consumer may have already moved it to
        // `generating`, in which case we must not remove it.
        query = query.where("queued_at", "=", new Date(queuedAt)).where("status", "=", "pending")
      }

      await query.execute()
    },
  }
}

