export type * from "./schema"

import { Hono, type Context } from "hono"
import { describeRoute, resolver } from "hono-openapi"
import { z } from "zod"

import type { Env } from "../env"
import type { Variables } from "../env"
import { TRAIL_EVAL_AGENT_IDS, agentIdToMetric } from "../lib/agents/trail-eval"
import { mapCheckpointToInfo } from "../lib/checkpoint-mapper"
import { getDb } from "../lib/db"
import type { Db } from "../lib/db/db-types"
import type { TrailRow } from "../lib/db/db-types"
import type { Repo } from "../lib/db/repos"
import {
  isValidTrailId,
  isValidBranchName,
  generateTrailId,
  generateCommentId,
  createBranchIfNotExists,
  checkBranchExists,
  checkInstallationWritePermission,
  compareBranchStatus,
  compareBranches,
  fetchPullRequestFiles,
  GitHubRateLimitError,
} from "../lib/github"
import { requireBearerAuth, requireAdmin } from "../lib/middleware"
import { recordSpanError } from "../lib/telemetry"
import { getValidGitHubTokenFromContext, getInstallationToken } from "../lib/token"
import type {
  User,
  TrailInfo,
  TrailMetadata,
  TrailDiscussion,
  TrailComment,
  TrailStatus,
  TrailPriority,
  TrailType,
  TrailReviewer,
  TrailReview,
  TrailReviews,
  CheckpointInfo,
} from "../types"

// ---- Constants ----

const VALID_PRIORITIES: TrailPriority[] = ["urgent", "high", "medium", "low", "none"]
const VALID_TYPES: TrailType[] = ["bug", "feature", "chore", "docs", "refactor"]
const VALID_TRAIL_STATUSES: TrailStatus[] = [
  "draft",
  "open",
  "in_progress",
  "in_review",
  "merged",
  "closed",
]

// ---- Helpers ----

const VALID_HOSTS = ["gh", "et"]

type TrailContext = Context<{ Bindings: Env; Variables: Variables }>

function isGitHubAuthError(err: unknown): boolean {
  if (!(err instanceof Error)) return false
  return /: 401$/.test(err.message)
}

// ---- Pre-request context resolver ----
// Eliminates repeated param extraction, validation, and access checks across handlers.

interface ResolvedRepoContext {
  db: Db
  userId: string
  repo: Repo
  repoFullName: string
  repoSlug: string
}

interface ResolvedTrailContext extends ResolvedRepoContext {
  trailId: string
  trail: TrailRow
}

interface ResolvedUserContext extends ResolvedRepoContext {
  user: User
}

interface ResolvedGitHubContext extends ResolvedUserContext {
  githubToken: string
}

async function resolveRepoContext(c: TrailContext): Promise<ResolvedRepoContext | Response> {
  const userId = c.get("userId") as string
  const host = c.req.param("host") ?? ""
  const owner = c.req.param("owner") ?? ""
  const repo = c.req.param("repo") ?? ""

  if (!VALID_HOSTS.includes(host)) {
    return c.json({ error: `Invalid host. Must be one of: ${VALID_HOSTS.join(", ")}` }, 400)
  }

  const repoSlug = `${host}/${owner}/${repo}`
  const repoFullName = `${owner}/${repo}`
  const db = getDb(c.env)

  const result = await db.repos.getByFullNameWithAccess(repoFullName, userId)
  let repoRecord: Repo | null = null

  if (result.status === "found") {
    repoRecord = result.repo
  } else if (result.status === "no_access") {
    repoRecord = await db.repos.getPublicByFullName(repoFullName)
  }

  if (!repoRecord) {
    return c.json({ error: "Repository not found" }, 404)
  }

  return { db, userId, repo: repoRecord, repoFullName, repoSlug }
}

async function resolveTrailContext(c: TrailContext): Promise<ResolvedTrailContext | Response> {
  const base = await resolveRepoContext(c)
  if (base instanceof Response) return base

  const trailId = c.req.param("trailId") ?? ""
  if (!isValidTrailId(trailId)) {
    return c.json({ error: "Invalid trail ID format" }, 400)
  }

  const trail = await base.db.trails.getByTrailId(base.repo.id, trailId)
  if (!trail) {
    return c.json({ error: "Trail not found" }, 404)
  }

  return { ...base, trailId, trail }
}

async function resolveUserContext(c: TrailContext): Promise<ResolvedUserContext | Response> {
  const base = await resolveRepoContext(c)
  if (base instanceof Response) return base

  const user = await base.db.users.findById(base.userId)
  if (!user) {
    return c.json({ error: "User not found" }, 404)
  }

  return { ...base, user }
}

async function resolveGitHubContext(c: TrailContext): Promise<ResolvedGitHubContext | Response> {
  const base = await resolveUserContext(c)
  if (base instanceof Response) return base

  let token: string | undefined
  if (base.user.github_token_enc) {
    const result = await getValidGitHubTokenFromContext(c, base.db, base.user)
    token = result.token
  }

  if (!token) {
    return c.json({ error: "GitHub token required" }, 401)
  }

  return { ...base, githubToken: token }
}

// Combines trail lookup with user resolution (for comment endpoints that need both)
async function resolveTrailWithUserContext(
  c: TrailContext,
): Promise<(ResolvedTrailContext & { user: ResolvedUserContext["user"] }) | Response> {
  const base = await resolveTrailContext(c)
  if (base instanceof Response) return base

  const user = await base.db.users.findById(base.userId)
  if (!user) {
    return c.json({ error: "User not found" }, 404)
  }

  return { ...base, user }
}

// Combines trail lookup with GitHub token resolution
async function resolveTrailWithGitHubContext(
  c: TrailContext,
): Promise<(ResolvedTrailContext & ResolvedGitHubContext) | Response> {
  const base = await resolveTrailContext(c)
  if (base instanceof Response) return base

  const user = await base.db.users.findById(base.userId)
  if (!user) {
    return c.json({ error: "User not found" }, 404)
  }

  let token: string | undefined
  if (user.github_token_enc) {
    const result = await getValidGitHubTokenFromContext(c, base.db, user)
    token = result.token
  }

  if (!token) {
    return c.json({ error: "GitHub token required" }, 401)
  }

  return { ...base, user, githubToken: token }
}

function trailRowToMetadata(row: TrailRow): TrailMetadata {
  const reviewers = Array.isArray(row.reviewers)
    ? (row.reviewers as unknown as TrailReviewer[])
    : []
  return {
    trail_id: row.trail_id,
    branch: row.branch,
    base: row.base,
    title: row.title,
    body: row.body ?? "",
    status: row.status,
    author: row.author,
    assignees: row.assignees,
    labels: row.labels,
    created_at: row.created_at,
    updated_at: row.updated_at,
    merged_at: row.merged_at,
    priority: (row.priority ?? "none") as TrailPriority,
    type: row.type as TrailType | undefined,
    reviewers,
    merge_base_sha: row.merge_base_sha,
    head_sha: row.head_sha,
  }
}

function trailRowToDiscussion(row: TrailRow): TrailDiscussion {
  const disc = row.discussion as unknown
  if (disc && typeof disc === "object" && "comments" in (disc as Record<string, unknown>)) {
    return disc as TrailDiscussion
  }
  return { comments: [] }
}

