  c: TrailContext,
): Promise<(ResolvedTrailContext & ResolvedGitHubContext) | Response> {
  const base = await resolveTrailContext(c)
  if (base instanceof Response) return base

  const user = await base.db.users.findById(base.userId)
  if (!user) {
    return c.json({ error: "User not found" }, 404)
  }

  let token: string | undefined
  if (user.github_token_enc) {
    const result = await getValidGitHubTokenFromContext(c, base.db, user)
    token = result.token
  }

  if (!token) {
    return c.json({ error: "GitHub token required" }, 401)
  }

  return { ...base, user, githubToken: token }
}

function trailRowToMetadata(row: TrailRow): TrailMetadata {
  const reviewers = Array.isArray(row.reviewers)
    ? (row.reviewers as unknown as TrailReviewer[])
    : []
  return {
    trail_id: row.trail_id,
    branch: row.branch,
    base: row.base,
    title: row.title,
    body: row.body ?? "",
    status: row.status,
    author: row.author,
    assignees: row.assignees,
    labels: row.labels,
    created_at: row.created_at,
    updated_at: row.updated_at,
    merged_at: row.merged_at,
    priority: (row.priority ?? "none") as TrailPriority,
    type: row.type as TrailType | undefined,
    reviewers,
    merge_base_sha: row.merge_base_sha,
    head_sha: row.head_sha,
  }
}

function trailRowToDiscussion(row: TrailRow): TrailDiscussion {
  const disc = row.discussion as unknown
  if (disc && typeof disc === "object" && "comments" in (disc as Record<string, unknown>)) {
    return disc as TrailDiscussion
  }
  return { comments: [] }
}

