const MUTATING_METHODS = new Set(["POST", "PUT", "PATCH", "DELETE"])
let csrfRequestInterceptorId: number | null = null

export type ConfigureApiSdkClientOptions = {
  baseUrl?: string
}

export function configureApiSdkClient(options: ConfigureApiSdkClientOptions = {}): void {
  // Base URL/credentials are initialized via client-fetch runtimeConfigPath.
  if (options.baseUrl) {
    client.setConfig({
      baseUrl: options.baseUrl,
      credentials: "include",
    })
  }

  if (
    csrfRequestInterceptorId === null ||
    !client.interceptors.request.exists(csrfRequestInterceptorId)
  ) {
    csrfRequestInterceptorId = client.interceptors.request.use((request) => {
      if (!MUTATING_METHODS.has(request.method.toUpperCase())) {
        return request
      }

      const csrfToken = getCookie("csrf")
      if (csrfToken) {
        request.headers.set("X-CSRF-Token", csrfToken)
      }

      return request
    })
  }
}

