import { ReactNode, useMemo } from "react"

import { Breadcrumbs, Button, FeedbackDialog } from "@/components"
import { SidebarFloatingIcon, SidebarInlineIcon } from "@/components/icons"
import { useAuth } from "@/domains/platform/auth"
import { usePageTitle } from "@/hooks/usePageTitle"

import { HeaderAccountMenu } from "./HeaderAccountMenu"
import { PrevNextNav, type PrevNextNavProps } from "./PrevNextNav"
import { useMobileMenu } from "./useMobileMenu"

interface BreadcrumbItem {
  href?: string
  label: string
  options?: { label: string; href: string }[]
  className?: string
}

interface PageProps {
  title?: ReactNode
  pageTitle?: string
  breadcrumbs?: BreadcrumbItem[]
  navigation?: PrevNextNavProps
  actions?: ReactNode
  subheader?: ReactNode
  children: ReactNode
  noPadding?: boolean
}

export function Page({
  title,
  pageTitle: pageTitleProp,
  breadcrumbs,
  navigation,
  actions,
  subheader,
  children,
  noPadding = false,
}: PageProps) {
  const { openMobileMenu } = useMobileMenu()
  const { user, login } = useAuth()
  const showBreadcrumbs = breadcrumbs && breadcrumbs.length > 0
  const showTitle = !showBreadcrumbs && title

  // Extract page title string from ReactNode or breadcrumbs
  const derivedPageTitle = useMemo(() => {
    if (pageTitleProp) return pageTitleProp
    if (showTitle && title) {
      // Extract text content from ReactNode
      if (typeof title === "string") {
        return title
      } else if (typeof title === "number") {
        return String(title)
      }
    } else if (showBreadcrumbs && breadcrumbs && breadcrumbs.length > 0) {
      // Use the last breadcrumb as the page title
      return breadcrumbs[breadcrumbs.length - 1].label
    }
    return null
  }, [pageTitleProp, title, breadcrumbs, showTitle, showBreadcrumbs])

  // Update document title using the shared hook
  usePageTitle(derivedPageTitle)

  return (
    <div>
      {/* Header */}
      <div className="sticky top-0 z-sticky bg-base">
        <div className="flex h-(--global-header-height) items-center justify-between gap-2 border-b border-subtle pr-2 pl-4 md:pl-6">
          <div className="flex min-w-0 items-center gap-2">
            <Button
              variant="outline"
              size="icon"
              onClick={openMobileMenu}
              aria-label="Open menu"
              className="group md:hidden"
            >
              <span className="relative flex size-[18px] items-center justify-center">
                <SidebarFloatingIcon className="absolute scale-100 opacity-100 transition-all duration-150 ease-out group-hover:scale-90 group-hover:opacity-0 group-focus:scale-90 group-focus:opacity-0" />
                <SidebarInlineIcon className="absolute scale-90 opacity-0 transition-all duration-150 ease-out group-hover:scale-100 group-hover:opacity-100 group-focus:scale-100 group-focus:opacity-100" />
              </span>
            </Button>
            {showBreadcrumbs && (
              <>
                <Breadcrumbs>
                  {breadcrumbs.map((item, index) => (
                    <Breadcrumbs.Item
                      key={index}
                      href={item.href}
                      options={item.options}
                      className={item.className}
                    >
                      {item.label}
                    </Breadcrumbs.Item>
                  ))}
                </Breadcrumbs>
                {navigation && <PrevNextNav {...navigation} />}
              </>
            )}
            {showTitle && <h1 className="text-xl font-bold text-default">{title}</h1>}
          </div>
          <div className="flex shrink-0 items-center gap-2">
            {actions}
            {user && (
              <>
                <div className="hidden sm:block">
                  <FeedbackDialog />
                </div>
                <HeaderAccountMenu />
              </>
            )}
            {!user && (
              <Button variant="attention" onClick={login}>
                Sign in
              </Button>
            )}
          </div>
        </div>

        {/* Subheader (e.g. tabs) */}
        {subheader}
      </div>

      {/* Content */}
      <div className={`isolate ${noPadding ? "" : "p-4 sm:p-6"}`}>{children}</div>
    </div>
  )
}

