import { notFound, redirect, rootRouteId } from "@tanstack/react-router"

import {
  fetchBranches,
  fetchCheckpoints,
  fetchCheckpointStatus,
} from "@/domains/platform/checkpoints/api"
import { ApiError } from "@/lib/api"

export const GH_PATH_PREFIX = "/gh"

/**
 * Determines the redirect target when a branch is not found.
 * Returns the branch to redirect to, or null if the request should 404.
 *
 * Only redirects when the missing branch matches the DB's stored default
 * (i.e., the system auto-navigated via a stale value). Random/typo branches 404.
 */
export function resolveRedirectBranch(
  branch: string,
  branchesData: { branches: string[]; default_branch: string; stored_default_branch: string },
): string | null {
  const isStaleDefault = branch === branchesData.stored_default_branch
  if (!isStaleDefault) return null

  if (branchesData.default_branch !== branch) {
    return branchesData.default_branch
  }

  return null
}

/**
 * Loader for /gh/$org/$repo/ — redirects to the default branch's checkpoints page.
 * Works for both authenticated and unauthenticated users.
 */
export function repoIndexLoader(pathPrefix: string) {
  return async ({ params }: { params: { org: string; repo: string } }) => {
    const { org, repo } = params

    let branchesData
    try {
      branchesData = await fetchBranches(org, repo)
    } catch (error) {
      if (error instanceof ApiError && error.message.includes("Repository not found")) {
        throw notFound({ routeId: rootRouteId })
      }
      throw error
    }

    throw redirect({
      to: `${pathPrefix}/$org/$repo/checkpoints/$branch` as "/gh/$org/$repo/checkpoints/$branch",
      params: { org, repo, branch: branchesData.default_branch },
    })
  }
}

/**
 * Loader for repo-scoped routes that require repo access.
 * Throws to the root notFoundComponent so unauthenticated users see a clean 404.
 */
export async function repoAccessLoader({ params }: { params: { org: string; repo: string } }) {
  const { org, repo } = params

  try {
    await fetchCheckpointStatus(org, repo)
  } catch (error) {
    if (error instanceof ApiError && error.message.includes("Repository not found")) {
      throw notFound({ routeId: rootRouteId })
    }
    throw error
  }
}

/**
 * Loader for /gh/$org/$repo/checkpoints/$branch/ — fetches checkpoints,
 * handles stale-branch redirects.
 */
export function checkpointsIndexLoader(pathPrefix: string) {
  return async ({ params }: { params: { org: string; repo: string; branch: string } }) => {
    const { org, repo, branch } = params

    try {
      await fetchCheckpoints(org, repo, branch)
    } catch (error) {
      if (error instanceof ApiError && error.status === 404) {
        const branchesData = await fetchBranches(org, repo).catch(() => null)
        if (branchesData) {
          const targetBranch = resolveRedirectBranch(branch, branchesData)

          if (targetBranch) {
            throw redirect({
              to: `${pathPrefix}/$org/$repo/checkpoints/$branch` as "/gh/$org/$repo/checkpoints/$branch",
              params: { org, repo, branch: targetBranch },
            })
          }
        }
        throw notFound()
      }
    }
  }
}

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query"

import type { GitHubReposResponse } from "@/domains/platform/repositories/api"

import {
  fetchTrails,
  fetchCollaborators,
  fetchTrailDetail,
  fetchTrailEvalRuns,
  fetchTrailEvalConfigs,
  fetchTrailFiles,
  fetchTrailReviews,
  fetchBranchProtection,
  fetchTrailSemanticDiff,
  triggerTrailSemanticDiff,
  updateTrailSettings,
  linkTrailBranch,
  type TrailsResponse,
  type TrailsQueryParams,
  type CollaboratorsResponse,
  type TrailDetailResponse,
  type TrailEvalRunsResponse,
  type TrailEvalConfigsResponse,
  type TrailFilesResponse,
  type TrailReviewsResponse,
  type BranchProtectionCheck,
  type TrailSemanticDiffResponse,
  type TrailSettingsResponse,
  type LinkTrailBranchRequest,
} from "../api"

export function useTrailsQuery(org: string, repo: string, params?: TrailsQueryParams) {
  return useQuery<TrailsResponse>({
    queryKey: ["github", "trails", org, repo, params ?? {}],
    queryFn: () => fetchTrails(org, repo, params),
    staleTime: 60 * 1000, // 1 minute
    placeholderData: (prev) => prev,
  })
}

export function useCollaboratorsQuery(org: string, repo: string) {
  return useQuery<CollaboratorsResponse>({
    queryKey: ["github", "collaborators", org, repo],
    queryFn: () => fetchCollaborators(org, repo),
    staleTime: 5 * 60 * 1000, // 5 minutes (collaborators don't change often)
  })
}

export function useTrailDetailQuery(org: string, repo: string, trailId: string) {
  return useQuery<TrailDetailResponse>({
    queryKey: ["github", "trails", org, repo, trailId],
    queryFn: () => fetchTrailDetail(org, repo, trailId),
    staleTime: 30 * 1000, // 30 seconds
  })
}

export function useTrailEvalRunsQuery(org: string, repo: string, trailId: string, enabled = true) {
  return useQuery<TrailEvalRunsResponse>({
    queryKey: ["github", "trail-eval-runs", org, repo, trailId],
    queryFn: () => fetchTrailEvalRuns(org, repo, trailId),
    enabled,
    staleTime: 10 * 1000, // 10 seconds
  })
}

export function useTrailEvalConfigsQuery() {
  return useQuery<TrailEvalConfigsResponse>({
