  return (
    <aside className="space-y-5 rounded-3xl border border-subtle bg-base p-5">
      <section>
        <div className="font-mono text-[11px] uppercase tracking-[0.2em] text-muted">Scope</div>
        <div className="mt-3 flex flex-wrap gap-2">
          {dispatch.covered_repos.map((repo) => (
            <Badge key={repo} className="bg-neutral-900 text-white dark:bg-neutral-100 dark:text-neutral-900">
              {repo}
            </Badge>
          ))}
        </div>
      </section>

      <section className="grid gap-3 text-sm text-muted">
        <div>
          <div className="font-mono text-[11px] uppercase tracking-[0.2em]">Window</div>
          <div className="mt-1">
            {new Date(dispatch.window.normalized_since).toLocaleString()} to{" "}
            {new Date(dispatch.window.normalized_until).toLocaleString()}
          </div>
        </div>
        <div>
          <div className="font-mono text-[11px] uppercase tracking-[0.2em]">Branches</div>
          <div className="mt-1">
            {dispatch.branches === "all" ? "All branches" : dispatch.branches.join(", ")}
          </div>
        </div>
        <div>
          <div className="font-mono text-[11px] uppercase tracking-[0.2em]">Voice</div>
          <div className="mt-1">{dispatch.voice ?? "neutral"}</div>
        </div>
        <div>
          <div className="font-mono text-[11px] uppercase tracking-[0.2em]">Created</div>
          <div className="mt-1">{new Date(dispatch.generated_at).toLocaleString()}</div>
        </div>
      </section>

      <section className="grid gap-2">
        <Button
          variant="outline"
          onClick={async () => {
            const success = await copyToClipboard(dispatch.generated_markdown)
            setCopiedMarkdown(success)
          }}
        >
          {copiedMarkdown ? "Copied markdown" : "Copy markdown"}
        </Button>

        <OpenInCliModal command={cliCommand} />

        <Button
          variant="outline"
          onClick={async () => {
            const success = await copyToClipboard(window.location.href)
            setCopiedLink(success)
          }}
        >
          {copiedLink ? "Copied link" : "Copy share link"}
        </Button>
      </section>
    </aside>
  )
}

import { useMutation, useQuery } from "@tanstack/react-query"

import {
  createDispatch,
  fetchDispatch,
  fetchOrgDispatches,
  fetchRepoDispatches,
  type CreateDispatchRequest,
  type CreateDispatchResponse,
  type DispatchDetail,
  type DispatchListResponse,
  type FetchDispatchListParams,
} from "../api"

export function useDispatchQuery(dispatchId: string) {
  return useQuery<DispatchDetail>({
    queryKey: ["dispatch", dispatchId],
    queryFn: () => fetchDispatch(dispatchId),
    enabled: dispatchId.length > 0,
    staleTime: 30 * 1000,
    refetchInterval: (query) => {
      const status = query.state.data?.status
      return status === "generating" ? 2000 : false
    },
  })
}

export function useRepoDispatchesQuery(
  org: string,
  repo: string,
  params?: FetchDispatchListParams,
) {
  return useQuery<DispatchListResponse>({
    queryKey: ["dispatches", "repo", org, repo, params ?? {}],
    queryFn: () => fetchRepoDispatches(org, repo, params),
    staleTime: 30 * 1000,
    placeholderData: (previous) => previous,
  })
}

export function useOrgDispatchesQuery(org: string, params?: FetchDispatchListParams) {
  return useQuery<DispatchListResponse>({
    queryKey: ["dispatches", "org", org, params ?? {}],
    queryFn: () => fetchOrgDispatches(org, params),
    staleTime: 30 * 1000,
    placeholderData: (previous) => previous,
  })
}

export function useCreateDispatchMutation() {
  return useMutation<CreateDispatchResponse, Error, CreateDispatchRequest>({
    mutationFn: (payload) => createDispatch(payload),
  })
}

import { request } from "@/lib/api"

export type DispatchStatus = "generating" | "complete" | "failed"
export type DispatchFormat = "markdown" | "text" | "json"
export type DispatchScopeMode = "repo" | "org"
export type DispatchBranchScope = "default" | "all" | "custom"
export type DispatchVoicePreset = "neutral" | "marvin" | "custom" | "upload"

export interface DispatchWindow {
  normalized_since: string
  normalized_until: string
  first_checkpoint_created_at: string | null
  last_checkpoint_created_at: string | null
}

export interface DispatchTotals {
  checkpoints: number
  used_checkpoint_count: number
  branches: number
  files_touched: number
}

export interface DispatchWarnings {
  access_denied_count: number
  pending_count: number
  failed_count: number
  unknown_count: number
  uncategorized_count: number
}

export interface DispatchBullet {
  checkpoint_id: string
  text: string
  source: "cloud_analysis" | "local_summary" | "commit_message"
  branch: string
  created_at: string
  labels: string[]
}

export interface DispatchSection {
  label: string
  bullets: DispatchBullet[]
}

export interface DispatchRepoGroup {
  full_name: string
  sections: DispatchSection[]
}

export interface DispatchSummary {
  id: string
  title: string
  excerpt: string
  status: DispatchStatus
  covered_repos: string[]
  voice: string | null
  generated_at: string
  window: DispatchWindow
  totals: DispatchTotals
}

export interface DispatchDetail extends DispatchSummary {
  fingerprint_hash: string | null
  branches: string[] | "all"
  web_url: string | null
  generated_markdown: string
  generated_text: string | null
  repos: DispatchRepoGroup[]
  warnings: DispatchWarnings
}

export interface DispatchListResponse {
  dispatches: DispatchSummary[]
  next_cursor: string | null
}

export interface FetchDispatchListParams {
  since?: string
  until?: string
  voice?: string
  q?: string
  cursor?: string
  limit?: number
}

export interface CreateDispatchRequest {
  repo?: string
  org?: string
  since: string
  until: string
  branches: string[] | "all"
  generate: boolean
  voice?: string
  dry_run?: boolean
  format?: DispatchFormat
}

export interface CreateDispatchResponse {
  id?: string
  title: string
  status?: DispatchStatus
  fingerprint_hash?: string
  web_url?: string
  covered_repos: string[]
  branches: string[] | "all"
  voice: string | null
  generated_at?: string
  window: DispatchWindow
  totals: DispatchTotals
  warnings: DispatchWarnings
  generated_markdown: string
  generated_text?: string | null
  repos: DispatchRepoGroup[]
  requested_generate: boolean
  dry_run: boolean
}

function buildSearchParams(params?: FetchDispatchListParams): string {
  const searchParams = new URLSearchParams()

  if (!params) {
    return ""
  }

  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === null || value === "") {
      continue
    }
    searchParams.set(key, String(value))
  }

  const query = searchParams.toString()
  return query ? `?${query}` : ""
}

export async function fetchDispatch(dispatchId: string): Promise<DispatchDetail> {
  return request<DispatchDetail>(`/api/v1/dispatches/${encodeURIComponent(dispatchId)}`)
}

export async function fetchRepoDispatches(
  org: string,
  repo: string,
  params?: FetchDispatchListParams,
): Promise<DispatchListResponse> {
  return request<DispatchListResponse>(
    `/api/v1/repos/${encodeURIComponent(org)}/${encodeURIComponent(repo)}/dispatches${buildSearchParams(params)}`,
  )
}

export async function fetchOrgDispatches(
  org: string,
  params?: FetchDispatchListParams,
): Promise<DispatchListResponse> {
  return request<DispatchListResponse>(
    `/api/v1/orgs/${encodeURIComponent(org)}/dispatches${buildSearchParams(params)}`,
  )
}

export async function createDispatch(
  payload: CreateDispatchRequest,
): Promise<CreateDispatchResponse> {
  return request<CreateDispatchResponse>("/api/v1/users/me/dispatches", {
    method: "POST",
    body: JSON.stringify(payload),
  })
}

export function buildDispatchMarkdownFallback(detail: {
  title: string
  repos: DispatchRepoGroup[]
}): string {
  const lines: string[] = [`# ${detail.title}`]

  for (const repo of detail.repos) {
    lines.push("", `## ${repo.full_name}`)
    for (const section of repo.sections) {
      lines.push("", `### ${section.label}`)
      for (const bullet of section.bullets) {
        lines.push(`- ${bullet.text}`)
      }
    }
  }

  return lines.join("\n").trim()
}

