interface DispatchPerOrgPageProps {
  org: string
  search: {
    since?: string
    until?: string
    voice?: string
    q?: string
  }
}

function buildParams(search: DispatchPerOrgPageProps["search"]): FetchDispatchListParams {
  return {
    since: search.since,
    until: search.until,
    voice: search.voice,
    q: search.q,
    limit: 20,
  }
}

export function DispatchPerOrgPage({ org, search }: DispatchPerOrgPageProps) {
  const navigate = useNavigate()
  const { data, isLoading, error } = useOrgDispatchesQuery(org, buildParams(search))

  return (
    <Page
      title={`${org} dispatches`}
      pageTitle={`${org} dispatches`}
      actions={
        <Button
          onClick={() => {
            navigate({
              to: "/dispatches/new",
              search: { org },
            })
          }}
