interface DispatchNewPageProps {
  initialRepo?: string
  initialOrg?: string
}

function buildCliCommand(args: {
  repo: string
  org: string
  scopeMode: "repo" | "org"
  since: string
  until: string
  branchScope: DispatchBranchScope
  customBranches: string
  generate: boolean
  voice: string
  format: DispatchFormat
}) {
  const flags: string[] = ["entire", "dispatch"]

  if (args.scopeMode === "repo" && args.repo) {
    flags.push(`--repo ${args.repo}`)
  }
  if (args.scopeMode === "org" && args.org) {
    flags.push(`--org ${args.org}`)
  }
  if (args.since) {
    flags.push(`--since "${args.since}"`)
  }
  if (args.until) {
    flags.push(`--until "${args.until}"`)
  }
  if (args.branchScope === "all") {
    flags.push("--branches all")
  }
  if (args.branchScope === "custom" && args.customBranches.trim()) {
    flags.push(`--branches "${args.customBranches.trim()}"`)
  }
  if (args.generate) {
    flags.push("--generate")
  }
  if (args.voice.trim()) {
    flags.push(`--voice "${args.voice.trim()}"`)
  }
  flags.push(`--format ${args.format}`)

  return flags.join(" ")
}

export function DispatchNewPage({ initialRepo = "", initialOrg = "" }: DispatchNewPageProps) {
  const navigate = useNavigate()
  const createDispatch = useCreateDispatchMutation()

  const [scopeMode, setScopeMode] = useState<"repo" | "org">(initialOrg ? "org" : "repo")
  const [repo, setRepo] = useState(initialRepo)
  const [org, setOrg] = useState(initialOrg)
  const [since, setSince] = useState("7d")
  const [until, setUntil] = useState("")
  const [branchScope, setBranchScope] = useState<DispatchBranchScope>("default")
  const [customBranches, setCustomBranches] = useState("")
  const [format, setFormat] = useState<DispatchFormat>("markdown")
  const [generate, setGenerate] = useState(true)
  const [voicePreset, setVoicePreset] = useState<DispatchVoicePreset>("neutral")
  const [voiceText, setVoiceText] = useState("")
  const [preview, setPreview] = useState<Awaited<
    ReturnType<typeof createDispatch.mutateAsync>
  > | null>(null)

  const effectiveVoice =
    voicePreset === "neutral" || voicePreset === "marvin"
      ? voicePreset
      : voicePreset === "custom"
        ? voiceText
        : voiceText

  const cliCommand = buildCliCommand({
    repo,
    org,
    scopeMode,
    since,
    until,
    branchScope,
    customBranches,
    generate,
    voice: effectiveVoice,
    format,
  })

  async function submit(dryRun: boolean) {
    const branches =
      branchScope === "all"
        ? "all"
        : branchScope === "custom"
          ? customBranches
              .split(",")
              .map((value) => value.trim())
              .filter(Boolean)
          : []

    const response = await createDispatch.mutateAsync({
      repo: scopeMode === "repo" ? repo : undefined,
      org: scopeMode === "org" ? org : undefined,
      since,
      until: until || new Date().toISOString(),
      branches: branches.length === 0 ? "all" : branches,
      generate,
      voice: effectiveVoice || undefined,
      dry_run: dryRun,
      format,
    })

    if (dryRun || !response.id) {
      startTransition(() => {
        setPreview(response)
      })
      return
    }

    navigate({
      to: "/dispatches/$dispatchId",
      params: { dispatchId: response.id },
    })
  }

  return (
    <Page title="New dispatch" pageTitle="New dispatch">
      <div className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_360px]">
        <form
          className="space-y-6"
          onSubmit={(event) => {
            event.preventDefault()
            void submit(false)
          }}
        >
          <section className="overflow-hidden rounded-[2rem] border border-subtle bg-base">
            <div className="border-b border-subtle bg-linear-to-br from-neutral-100 via-base to-neutral-200 px-6 py-5 dark:from-neutral-900 dark:via-base dark:to-neutral-950">
              <div className="font-mono text-[11px] uppercase tracking-[0.22em] text-muted">
                Scope
              </div>
              <h2 className="mt-3 text-xl font-semibold text-default">What should this cover?</h2>
            </div>
            <div className="grid gap-5 px-6 py-6">
              <div className="flex flex-wrap gap-2">
                {(["repo", "org"] as const).map((mode) => (
                  <button
                    key={mode}
                    type="button"
                    onClick={() => setScopeMode(mode)}
                    className={`rounded-full border px-4 py-2 text-sm transition-colors ${
                      scopeMode === mode
                        ? "border-neutral-900 bg-neutral-900 text-white dark:border-neutral-100 dark:bg-neutral-100 dark:text-neutral-900"
                        : "border-subtle bg-base text-default"
                    }`}
                  >
