import { useNavigate } from "@tanstack/react-router"

import { Empty, EmptyContent, EmptyDescription, EmptyTitle } from "@/components/Empty"
import { Input, Skeleton } from "@/components"
import Button from "@/components/Button"
import { Page } from "@/domains/platform/components/Page"

import type { FetchDispatchListParams } from "../api"
import { DispatchCard } from "../components/DispatchCard"
import { useRepoDispatchesQuery } from "../hooks/useDispatch"

export interface DispatchListSearchParams {
  since?: string
  until?: string
  voice?: string
  q?: string
}

interface DispatchPerRepoPageProps {
  org: string
  repo: string
  search: DispatchListSearchParams
}

function buildParams(search: DispatchListSearchParams): FetchDispatchListParams {
  return {
    since: search.since,
    until: search.until,
    voice: search.voice,
    q: search.q,
    limit: 20,
  }
}

export function DispatchPerRepoPage({ org, repo, search }: DispatchPerRepoPageProps) {
  const navigate = useNavigate()
  const { data, isLoading, error } = useRepoDispatchesQuery(org, repo, buildParams(search))

  return (
    <Page
      title={`Dispatches for ${org}/${repo}`}
      pageTitle={`Dispatches for ${org}/${repo}`}
      actions={
        <Button
          onClick={() => {
            navigate({
              to: "/dispatches/new",
              search: { repo: `${org}/${repo}` },
            })
          }}
        >
          New dispatch
        </Button>
      }
    >
      <div className="space-y-5">
        <section className="grid gap-3 rounded-3xl border border-subtle bg-base p-5 md:grid-cols-[1fr_180px_180px]">
          <Input
            placeholder="Search title and body"
            value={search.q ?? ""}
            onChange={(event) => {
              navigate({
                to: ".",
                search: (previous) => ({ ...previous, q: event.target.value || undefined }),
              })
            }}
          />
          <Input
            placeholder="Since (7d, 30d, 2026-04-01)"
            value={search.since ?? ""}
            onChange={(event) => {
              navigate({
                to: ".",
                search: (previous) => ({ ...previous, since: event.target.value || undefined }),
              })
            }}
          />
          <Input
            placeholder="Voice"
            value={search.voice ?? ""}
            onChange={(event) => {
              navigate({
                to: ".",
                search: (previous) => ({ ...previous, voice: event.target.value || undefined }),
              })
            }}
          />
        </section>

        {isLoading && (
          <div className="grid gap-4">
            <Skeleton className="h-48 rounded-3xl" />
            <Skeleton className="h-48 rounded-3xl" />
          </div>
        )}

        {!isLoading && error && (
          <Empty>
            <EmptyTitle>Dispatches unavailable</EmptyTitle>
            <EmptyDescription>{error.message}</EmptyDescription>
          </Empty>
        )}

        {!isLoading && !error && data && data.dispatches.length === 0 && (
          <Empty>
            <EmptyTitle>No dispatches yet</EmptyTitle>
            <EmptyDescription>
              No visible dispatches were found for this repository with the current filters.
            </EmptyDescription>
            <EmptyContent>
              <Button
                onClick={() =>
                  navigate({ to: "/dispatches/new", search: { repo: `${org}/${repo}` } })
                }
              >
                Create one
              </Button>
            </EmptyContent>
          </Empty>
        )}

        {!isLoading && data && data.dispatches.length > 0 && (
          <div className="grid gap-4">
            {data.dispatches.map((dispatch) => (
              <DispatchCard key={dispatch.id} dispatch={dispatch} />
            ))}
          </div>
        )}
      </div>
    </Page>
  )
}

