import { useMatch } from "@tanstack/react-router"
import { useMemo } from "react"

export type RepoSection = "overview" | "checkpoints" | "trails" | "runners"

interface RepoNavMatch {
  params: {
    org: string
    repo: string
  }
  section: RepoSection
}

export function useRepoNavState() {
  const overviewMatch = useMatch({
    from: "/_repo/gh/$org/$repo/overview/",
    shouldThrow: false,
  })

  const checkpointsIndexMatch = useMatch({
    from: "/_repo/gh/$org/$repo/checkpoints/",
    shouldThrow: false,
  })
  const checkpointsBranchMatch = useMatch({
    from: "/_repo/gh/$org/$repo/checkpoints/$branch",
    shouldThrow: false,
  })
  const checkpointsBranchIndexMatch = useMatch({
    from: "/_repo/gh/$org/$repo/checkpoints/$branch/",
    shouldThrow: false,
  })
  const checkpointDetailMatch = useMatch({
    from: "/_repo/gh/$org/$repo/checkpoints/$branch/$checkpointId",
    shouldThrow: false,
  })
  const commitMatch = useMatch({
    from: "/_repo/gh/$org/$repo/commit/$commitSha",
    shouldThrow: false,
  })
  const commitBranchMatch = useMatch({
    from: "/_repo/gh/$org/$repo/commit/$branch/$commitSha",
    shouldThrow: false,
  })

  const trailsMatch = useMatch({
    from: "/_repo/gh/$org/$repo/trails",
    shouldThrow: false,
  })
  const trailsIndexMatch = useMatch({
    from: "/_repo/gh/$org/$repo/trails/",
    shouldThrow: false,
  })
  const trailDetailMatch = useMatch({
    from: "/_repo/gh/$org/$repo/trails/$trailId",
    shouldThrow: false,
  })

  const runnersMatch = useMatch({
    from: "/_repo/gh/$org/$repo/runners",
    shouldThrow: false,
  })
  const runnersIndexMatch = useMatch({
    from: "/_repo/gh/$org/$repo/runners/",
    shouldThrow: false,
  })
  const runnerDetailMatch = useMatch({
    from: "/_repo/gh/$org/$repo/runners/$runId",
    shouldThrow: false,
  })

  const activeMatch = useMemo<RepoNavMatch | null>(() => {
    if (overviewMatch) {
      return { params: overviewMatch.params, section: "overview" }
    }
    if (
      checkpointsIndexMatch ||
      checkpointsBranchMatch ||
      checkpointsBranchIndexMatch ||
      checkpointDetailMatch ||
      commitMatch ||
      commitBranchMatch
    ) {
      const match =
        checkpointsIndexMatch ??
        checkpointsBranchIndexMatch ??
        checkpointsBranchMatch ??
        checkpointDetailMatch ??
        commitBranchMatch ??
        commitMatch
      if (!match) return null
      return { params: match.params, section: "checkpoints" }
    }
    if (trailsMatch || trailsIndexMatch || trailDetailMatch) {
      const match = trailsIndexMatch ?? trailsMatch ?? trailDetailMatch
      if (!match) return null
      return { params: match.params, section: "trails" }
    }
    if (runnersMatch || runnersIndexMatch || runnerDetailMatch) {
      const match = runnersIndexMatch ?? runnersMatch ?? runnerDetailMatch
      if (!match) return null
      return { params: match.params, section: "runners" }
    }

    return null
  }, [
    checkpointDetailMatch,
    checkpointsBranchIndexMatch,
    checkpointsBranchMatch,
    checkpointsIndexMatch,
    commitBranchMatch,
    commitMatch,
    overviewMatch,
    runnerDetailMatch,
    runnersIndexMatch,
    runnersMatch,
    trailDetailMatch,
    trailsIndexMatch,
    trailsMatch,
  ])

  return {
    activeRepoFullName: activeMatch ? `${activeMatch.params.org}/${activeMatch.params.repo}` : null,
    activeSection: activeMatch?.section ?? null,
  }
}

