const { recordRecentRepoByName, removeRecentRepo } = useRecentRepoActions()
const lastCheckedActiveRepoRef = useRef<string | null>(null)

// Track repo visits and auto-expand the active repo
const [expandedRepos, setExpandedRepos] = usePersistentState(
  "sidebar-expanded-repos",
  () => (activeRepoFullName != null ? new Set([activeRepoFullName]) : new Set<string>()),
  {
    serialize: (value) => JSON.stringify([...value]),
    deserialize: (raw) => {
      const parsed = JSON.parse(raw)

      if (!Array.isArray(parsed)) {
        return new Set<string>()
      }

      return new Set(parsed.filter((value): value is string => typeof value === "string"))
    },
  },
)

const toggleRepoExpanded = (fullName: string) => {
  setExpandedRepos((prev) => {
    const next = new Set(prev)
    if (next.has(fullName)) {
      next.delete(fullName)
    } else {
      next.add(fullName)
    }
    return next
  })
}

useEffect(() => {
  if (activeRepoFullName == null) {
    return
  }

  setExpandedRepos((prev) => {
    if (prev.has(activeRepoFullName)) return prev

    return new Set(prev).add(activeRepoFullName)
  })
}, [activeRepoFullName, setExpandedRepos])

useEffect(() => {
  if (activeRepoFullName == null) {
    lastCheckedActiveRepoRef.current = null
    return
  }

  if (!hasLoadedPreferences) {
    return
  }

  if (lastCheckedActiveRepoRef.current === activeRepoFullName) {
    return
  }

  lastCheckedActiveRepoRef.current = activeRepoFullName

  if (!hasRecentRepoPreference(activeRepoFullName)) {
    recordRecentRepoByName({ fullName: activeRepoFullName })
  }
}, [activeRepoFullName, hasLoadedPreferences, hasRecentRepoPreference, recordRecentRepoByName])

const navItems: NavItem[] = [
  {
    to: "/overview",
    icon: <DashboardIcon className="shrink-0 transition-transform duration-300" />,
    label: "Overview",
    requiresAuth: true,
  },
  {
    to: "/repositories",
    icon: <RepositoryIcon size={18} className="shrink-0 transition-transform duration-300" />,
    label: "Repositories",
    requiresAuth: true,
  },
]

const aboutSubItems = [
  { to: "/home", label: "Home" },
  { to: "/company", label: "Company" },
  { to: "/vision", label: "Vision" },
  { to: "/blog", label: "Blog" },
]

const visibleNavItems = navItems.filter(
  (item) => (!item.requiresAuth || user) && (!item.adminOnly || user?.is_admin),
)
const activeRepo = activeRepoFullName

// If the active repo isn't already in pinned or recent, surface it in its own
// "Current" section so visitors (including unauthenticated users viewing a
// public repo) can see the repo they're on highlighted in the sidebar.
const activeRepoInLists =
  activeRepo != null && (pinnedRepos.includes(activeRepo) || recentRepos.includes(activeRepo))
const showCurrentRepo = showFullContent && activeRepo != null && !activeRepoInLists

const hasPinned = showFullContent && pinnedRepos.length > 0
const hasRecent = showFullContent && recentRepos.length > 0
const hasRepoSections = showCurrentRepo || hasPinned || hasRecent

return (
  <div className="flex h-full min-h-0 flex-1 flex-col gap-4 overflow-y-auto py-2">
    <SidebarNavList>
      {visibleNavItems.map((item) => (
        <SidebarNavItem
          key={item.to}
          to={item.to}
          icon={item.icon}
          label={item.label}
          showFullContent={showFullContent}
          adminOnly={item.adminOnly}
          onClick={onNavigate}
        />
      ))}
      {isSearchEnabled && <SidebarSearchButton showFullContent={showFullContent} />}
    </SidebarNavList>

    {/* Separator between nav links and repo sections */}
    {hasRepoSections && visibleNavItems.length > 0 && <hr className="mx-2 border-subtle" />}

    {/* CURRENT repo (shown when the active repo isn't pinned or in recent) */}
    {showCurrentRepo && activeRepo != null && (
      <div>
        <div className="flex items-center px-5 pb-1">
          <span className="font-mono text-xs font-normal tracking-wider text-muted uppercase">
            Current
          </span>
        </div>
        <ul className="flex flex-col gap-px">
          <SidebarRepoItem
            fullName={activeRepo}
            isExpanded={expandedRepos.has(activeRepo)}
            onToggle={() => toggleRepoExpanded(activeRepo)}
            isActive
            isPinned={false}
            isAdmin={!!user?.is_admin}
            runnersEnabled={false}
            trailsEnabled={false}
            showFullContent={showFullContent}
            onNavigate={onNavigate}
            activeSection={activeSection}
          />
        </ul>
      </div>
    )}

    {/* PINNED repos */}
    {hasPinned && (
      <div>
        <div className="flex items-center px-5 pb-1">
          <span className="font-mono text-xs font-normal tracking-wider text-muted uppercase">
            Pinned
          </span>
        </div>
        <ul className="flex flex-col gap-px">
          {pinnedRepoItems.map((repoData) => {
            const fullName = repoData.full_name
            return (
              <SidebarRepoItem
                key={fullName}
                fullName={fullName}
                isExpanded={expandedRepos.has(fullName)}
                onToggle={() => toggleRepoExpanded(fullName)}
                isActive={activeRepo === fullName}
                isPinned={true}
                onPin={() => pinRepo(fullName, repoData.repo_id)}
                onUnpin={() => unpinRepo(fullName, repoData.repo_id)}
                isAdmin={!!user?.is_admin}
                runnersEnabled={repoData.runners_enabled}
                trailsEnabled={repoData.trails_enabled}
                showFullContent={showFullContent}
                onNavigate={onNavigate}
                activeSection={activeRepo === fullName ? activeSection : null}
              />
            )
          })}
        </ul>
      </div>
    )}

    {/* RECENT repos */}
