import { Dropdown, DropdownTrigger, DropdownContent, DropdownItem } from "@/components/Dropdown"
import { Skeleton } from "@/components/Skeleton"
import { Page } from "@/domains/platform/components/Page"
import { useGlobalSearch } from "@/domains/platform/search/hooks"
import { openSearchResult } from "@/domains/platform/search/navigation"
import { SearchResultCard } from "@/domains/platform/search/SearchResultCard"
import { checkpointTitle, type SearchResult } from "@/domains/platform/search/types"
import { useRecentSearches } from "@/domains/platform/search/useRecentSearches"
import { getLocalFeatureFlagOverride, getGlobalFeatureFlagOverride } from "@/lib/featureFlags"

type SortOption = "relevance" | "date" | "author" | "title"

interface SearchPageParams {
  q?: string
  types?: string
  repo?: string
  author?: string
  date?: string
  branch?: string
  sort?: string
  page?: string
}

export const Route = createFileRoute("/_authenticated/search")({
  beforeLoad: ({ context }) => {
    // Respect dev overrides (VITE_FORCE_FLAG_SEMANTIC_SEARCH, VITE_FORCE_ALL_FLAGS)
    const localOverride = getLocalFeatureFlagOverride("semantic-search")
    if (localOverride !== undefined) {
      if (!localOverride) throw notFound()
      return
    }
    const globalOverride = getGlobalFeatureFlagOverride()
    if (globalOverride !== undefined) {
      if (!globalOverride) throw notFound()
      return
    }
    if (!context.auth.user?.feature_flags?.["semantic-search"]) {
      throw notFound()
    }
  },
  component: SearchPage,
  validateSearch: (search: Record<string, unknown>): SearchPageParams => ({
    q: (search.q as string) || undefined,
    types: (search.types as string) || undefined,
    repo: (search.repo as string) || undefined,
    author: (search.author as string) || undefined,
    date: (search.date as string) || undefined,
    branch: (search.branch as string) || undefined,
    sort: (search.sort as string) || undefined,
    page: (search.page as string) || undefined,
  }),
})

function SearchPage() {
  const navigate = useNavigate({ from: "/search" })
  const params = Route.useSearch()
  const { recent } = useRecentSearches()

  const q = params.q ?? ""
  const pageRaw = params.page ? parseInt(params.page, 10) : 1
  const page = Number.isNaN(pageRaw) ? 1 : pageRaw
  const PAGE_SIZE = 20

  const posthog = usePostHog()
  const startTimeRef = useRef<number | null>(null)
  const [elapsedMs, setElapsedMs] = useState<number | null>(null)
  const [branchSearch, setBranchSearch] = useState("")

  // Fetch all results for q only — filters are applied client-side
  const { data, isFetching, isError } = useGlobalSearch(
    q.trim().length > 0 ? { q, limit: 100 } : null,
  )

  useEffect(() => {
    if (isFetching) {
      startTimeRef.current = Date.now()
    } else if (startTimeRef.current !== null) {
      const clientMs = Date.now() - startTimeRef.current
      setElapsedMs(clientMs)
      startTimeRef.current = null

      if (data && q.trim()) {
        posthog.capture("search_executed", {
          query: q,
          query_length: q.length,
          source: "search_page",
          result_count: data.total,
          client_latency_ms: clientMs,
          timing_total_ms: data.timing?.total_ms ?? null,
          timing_keyword_ms: data.timing?.keyword_ms ?? null,
          timing_embedding_ms: data.timing?.embedding_ms ?? null,
          timing_vector_ms: data.timing?.vector_ms ?? null,
          timing_rerank_ms: data.timing?.rerank_ms ?? null,
        })
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- intentionally fires only on isFetching transitions
  }, [isFetching])

  // Client-side filtering
  const allResults = useMemo(() => data?.results ?? [], [data?.results])
  // True when we hit the 100-result cap — there may be additional matches in the DB
  const isCapped = allResults.length >= 100
  const [now] = useState(() => Date.now())
  const filtered = useMemo(() => {
    return allResults.filter((r) => {
      if (params.types) {
        const types = params.types.split(",").filter(Boolean)
        if (types.length && !types.includes(r.type === "repo" ? "repos" : "checkpoints"))
          return false
      }
      if (params.repo) {
        const fullName = r.type === "repo" ? r.data.fullName : `${r.data.org}/${r.data.repo}`
        if (fullName !== params.repo) return false
      }
      if (params.author && r.type === "checkpoint") {
        const match = r.data.authorUsername ?? r.data.author
        if (!match.toLowerCase().includes(params.author.toLowerCase())) return false
      }
      if (params.date && r.type === "checkpoint") {
        const ms = params.date === "week" ? 7 : 30
        const threshold = new Date(now - ms * 24 * 60 * 60 * 1000)
        if (new Date(r.data.createdAt) < threshold) return false
      }
      if (params.branch && r.type === "checkpoint") {
        if (r.data.branch !== params.branch) return false
      }
      return true
    })
  }, [allResults, params.types, params.repo, params.author, params.date, params.branch, now])

  const sort = (params.sort ?? "relevance") as SortOption

  const sorted = useMemo(
    () =>
      [...filtered].sort((a, b) => {
        if (sort === "date") {
          const aDate = a.type === "checkpoint" ? a.data.createdAt : ""
          const bDate = b.type === "checkpoint" ? b.data.createdAt : ""
          return bDate.localeCompare(aDate)
        }
        if (sort === "author") {
          const aAuthor =
            a.type === "checkpoint" ? (a.data.authorUsername ?? a.data.author) : a.data.org
          const bAuthor =
            b.type === "checkpoint" ? (b.data.authorUsername ?? b.data.author) : b.data.org
          return aAuthor.localeCompare(bAuthor)
        }
        if (sort === "title") {
          const aTitle =
            a.type === "checkpoint"
              ? checkpointTitle(a.data.prompt, a.data.commitMessage)
              : a.data.fullName
          const bTitle =
            b.type === "checkpoint"
              ? checkpointTitle(b.data.prompt, b.data.commitMessage)
              : b.data.fullName
          return aTitle.localeCompare(bTitle)
        }
        return b.searchMeta.score - a.searchMeta.score
      }),
    [filtered, sort],
  )

  const repoCount = allResults.filter((r) => r.type === "repo").length
  const checkpointCount = allResults.filter((r) => r.type === "checkpoint").length

  const total = sorted.length
  const totalPages = Math.ceil(total / PAGE_SIZE)
  const results = sorted.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE)

  // Date counts for the date filter (checkpoint results within each window)
  const dateCountsInResults = useMemo(() => {
    const counts: Record<"week" | "month", number> = { week: 0, month: 0 }
    for (const r of allResults) {
      if (r.type !== "checkpoint") continue
      const created = new Date(r.data.createdAt).getTime()
      if (created >= now - 7 * 24 * 60 * 60 * 1000) counts.week++
