  if (args.branchScope === "custom" && args.customBranches.trim()) {
    flags.push(`--branches "${args.customBranches.trim()}"`)
  }
  if (args.generate) {
    flags.push("--generate")
  }
  if (args.voice.trim()) {
    flags.push(`--voice "${args.voice.trim()}"`)
  }
  flags.push(`--format ${args.format}`)

