import { useMutation, useQuery } from "@tanstack/react-query"

import {
  createDispatch,
  fetchDispatch,
  fetchOrgDispatches,
  fetchRepoDispatches,
  type CreateDispatchRequest,
  type CreateDispatchResponse,
  type DispatchDetail,
  type DispatchListResponse,
  type FetchDispatchListParams,
} from "../api"

export function useDispatchQuery(dispatchId: string) {
  return useQuery<DispatchDetail>({
    queryKey: ["dispatch", dispatchId],
    queryFn: () => fetchDispatch(dispatchId),
    enabled: dispatchId.length > 0,
    staleTime: 30 * 1000,
    refetchInterval: (query) => {
      const status = query.state.data?.status
      return status === "generating" ? 2000 : false
    },
  })
}

export function useRepoDispatchesQuery(
  org: string,
  repo: string,
  params?: FetchDispatchListParams,
) {
  return useQuery<DispatchListResponse>({
    queryKey: ["dispatches", "repo", org, repo, params ?? {}],
    queryFn: () => fetchRepoDispatches(org, repo, params),
    staleTime: 30 * 1000,
    placeholderData: (previous) => previous,
  })
}

export function useOrgDispatchesQuery(org: string, params?: FetchDispatchListParams) {
  return useQuery<DispatchListResponse>({
    queryKey: ["dispatches", "org", org, params ?? {}],
    queryFn: () => fetchOrgDispatches(org, params),
    staleTime: 30 * 1000,
    placeholderData: (previous) => previous,
  })
}

export function useCreateDispatchMutation() {
  return useMutation<CreateDispatchResponse, Error, CreateDispatchRequest>({
    mutationFn: (payload) => createDispatch(payload),
  })
}

