export function Sidebar({
  isDesktopExpanded,
  isFloating,
  isMobileMenuOpen,
  onCollapseDesktop,
  onExpandDesktop,
  onFloat,
  onCloseFloat,
  onCloseMobile,
}: SidebarProps) {
  // Show full content when expanded, floating, or mobile menu open
  const showFullContent = isDesktopExpanded || isFloating || isMobileMenuOpen

  // Close floating sidebar on touch nav — on mouse, hover keeps it open
  const handleNavigate = () => {
    if (isMobileMenuOpen) {
      onCloseMobile()
    } else if (isFloating && !window.matchMedia("(hover: hover)").matches) {
      onCloseFloat()
