        onCollapseDesktop={onCollapseDesktop}
        onExpandDesktop={onExpandDesktop}
        onCloseMobile={onCloseMobile}
      />

      <SidebarNavigation showFullContent={showFullContent} onNavigate={handleNavigate} />
