// Eliminates repeated param extraction, validation, and access checks across handlers.

interface ResolvedRepoContext {
  db: Db
  userId: string
  repo: Repo
  repoFullName: string
  repoSlug: string
}

interface ResolvedTrailContext extends ResolvedRepoContext {
  trailId: string
