import { afterAll, describe, it, expect, beforeEach, vi } from "vitest"

// Mock global fetch before importing the module under test
const originalFetch = globalThis.fetch
const mockFetch = vi.fn()
vi.stubGlobal("fetch", mockFetch)

// Minimal KV mock that supports get (with "json" type) and put
function createMockKV() {
  const store = new Map<string, string>()
  return {
    store,
    get: vi.fn(async (key: string, type?: string) => {
      const val = store.get(key)
      if (val == null) return null
      if (type === "json") return JSON.parse(val)
      return val
    }),
    put: vi.fn(async (key: string, value: string, _opts?: unknown) => {
      store.set(key, value)
    }),
  } as unknown as KVNamespace & { store: Map<string, string> }
}

// Import cacheRoutes after mocking fetch
const { cacheRoutes } = await import("./cache")

afterAll(() => {
  vi.stubGlobal("fetch", originalFetch)
})

describe("GET /github-stars", () => {
  let mockKV: ReturnType<typeof createMockKV>

  beforeEach(() => {
    mockKV = createMockKV()
    mockFetch.mockReset()
  })

  it("returns star count from GitHub API and caches it", async () => {
    mockFetch.mockResolvedValueOnce(
      new Response(JSON.stringify({ stargazers_count: 2900 }), {
        status: 200,
        headers: { "Content-Type": "application/json" },
      }),
    )

    const res = await cacheRoutes.request("/github-stars", {}, { ENTIRE_CACHE: mockKV })

    expect(res.status).toBe(200)
    expect(await res.json()).toEqual({ stars: 2900 })
    // Verify it was cached in KV with 1-hour TTL
    expect(mockKV.put).toHaveBeenCalledWith(
      "github-stars:entireio/cli",
      JSON.stringify({ stars: 2900 }),
      { expirationTtl: 3600 },
    )
  })

  it("returns cached value from KV without calling GitHub", async () => {
    // Pre-populate the KV cache
    mockKV.store.set("github-stars:entireio/cli", JSON.stringify({ stars: 3100 }))

    const res = await cacheRoutes.request("/github-stars", {}, { ENTIRE_CACHE: mockKV })

    expect(res.status).toBe(200)
    expect(await res.json()).toEqual({ stars: 3100 })
    // Should NOT have called fetch
    expect(mockFetch).not.toHaveBeenCalled()
  })

  it("returns 502 with { stars: null } when GitHub API returns 500", async () => {
    mockFetch.mockResolvedValueOnce(new Response("Internal Server Error", { status: 500 }))

    const res = await cacheRoutes.request("/github-stars", {}, { ENTIRE_CACHE: mockKV })

    expect(res.status).toBe(502)
    expect(await res.json()).toEqual({ stars: null })
    expect(mockKV.put).not.toHaveBeenCalled()
  })

  it("returns 502 when fetch throws a network error", async () => {
    mockFetch.mockRejectedValueOnce(new TypeError("fetch failed"))

    const res = await cacheRoutes.request("/github-stars", {}, { ENTIRE_CACHE: mockKV })

    expect(res.status).toBe(502)
    expect(await res.json()).toEqual({ stars: null })
    expect(mockKV.put).not.toHaveBeenCalled()
  })

  it("returns 502 when GitHub API returns JSON with unexpected shape", async () => {
    mockFetch.mockResolvedValueOnce(
      new Response(JSON.stringify({ id: 123, name: "cli" }), {
        status: 200,
        headers: { "Content-Type": "application/json" },
      }),
    )

    const res = await cacheRoutes.request("/github-stars", {}, { ENTIRE_CACHE: mockKV })

    expect(res.status).toBe(502)
    expect(await res.json()).toEqual({ stars: null })
    // Should NOT cache an invalid response
    expect(mockKV.put).not.toHaveBeenCalled()
  })

  it("returns 502 when GitHub API returns JSON null (valid JSON)", async () => {
    mockFetch.mockResolvedValueOnce(
      new Response("null", {
        status: 200,
        headers: { "Content-Type": "application/json" },
      }),
    )

    const res = await cacheRoutes.request("/github-stars", {}, { ENTIRE_CACHE: mockKV })

    expect(res.status).toBe(502)
    expect(await res.json()).toEqual({ stars: null })
    expect(mockKV.put).not.toHaveBeenCalled()
  })

  it("returns 502 when stargazers_count is not a number", async () => {
    mockFetch.mockResolvedValueOnce(
      new Response(JSON.stringify({ stargazers_count: "many" }), {
        status: 200,
        headers: { "Content-Type": "application/json" },
      }),
    )

    const res = await cacheRoutes.request("/github-stars", {}, { ENTIRE_CACHE: mockKV })

    expect(res.status).toBe(502)
    expect(await res.json()).toEqual({ stars: null })
    expect(mockKV.put).not.toHaveBeenCalled()
  })

  it("returns 502 when GitHub API returns non-JSON (e.g. HTML error page)", async () => {
    mockFetch.mockResolvedValueOnce(
      new Response("<html>Service Unavailable</html>", {
        status: 200,
        headers: { "Content-Type": "text/html" },
      }),
    )

    const res = await cacheRoutes.request("/github-stars", {}, { ENTIRE_CACHE: mockKV })

    expect(res.status).toBe(502)
    expect(await res.json()).toEqual({ stars: null })
  })
})

import { startTransition, useState } from "react"
import { useNavigate } from "@tanstack/react-router"

import { Badge } from "@/components/Badge"
import { Input } from "@/components"
import Button from "@/components/Button"
import Textarea from "@/components/Textarea"
import { Page } from "@/domains/platform/components/Page"

import {
  type DispatchBranchScope,
  type DispatchFormat,
  type DispatchVoicePreset,
} from "../api"
import { DispatchPreviewPane } from "../components/DispatchPreviewPane"
import { VoicePicker } from "../components/VoicePicker"
import { useCreateDispatchMutation } from "../hooks/useDispatch"

interface DispatchNewPageProps {
  initialRepo?: string
  initialOrg?: string
}

function buildCliCommand(args: {
  repo: string
  org: string
  scopeMode: "repo" | "org"
  since: string
  until: string
  branchScope: DispatchBranchScope
  customBranches: string
  generate: boolean
  voice: string
  format: DispatchFormat
}) {
  const flags: string[] = ["entire", "dispatch"]

  if (args.scopeMode === "repo" && args.repo) {
    flags.push(`--repo ${args.repo}`)
  }
  if (args.scopeMode === "org" && args.org) {
    flags.push(`--org ${args.org}`)
  }
  if (args.since) {
    flags.push(`--since "${args.since}"`)
  }
  if (args.until) {
    flags.push(`--until "${args.until}"`)
  }
  if (args.branchScope === "all") {
    flags.push("--branches all")
  }
  if (args.branchScope === "custom" && args.customBranches.trim()) {
    flags.push(`--branches "${args.customBranches.trim()}"`)
  }
  if (args.generate) {
    flags.push("--generate")
  }
  if (args.voice.trim()) {
    flags.push(`--voice "${args.voice.trim()}"`)
  }
  flags.push(`--format ${args.format}`)

  return flags.join(" ")
}

export function DispatchNewPage({ initialRepo = "", initialOrg = "" }: DispatchNewPageProps) {
  const navigate = useNavigate()
  const createDispatch = useCreateDispatchMutation()

  const [scopeMode, setScopeMode] = useState<"repo" | "org">(initialOrg ? "org" : "repo")
  const [repo, setRepo] = useState(initialRepo)
  const [org, setOrg] = useState(initialOrg)
  const [since, setSince] = useState("7d")
  const [until, setUntil] = useState("")
  const [branchScope, setBranchScope] = useState<DispatchBranchScope>("default")
  const [customBranches, setCustomBranches] = useState("")
  const [format, setFormat] = useState<DispatchFormat>("markdown")
  const [generate, setGenerate] = useState(true)
  const [voicePreset, setVoicePreset] = useState<DispatchVoicePreset>("neutral")
  const [voiceText, setVoiceText] = useState("")
  const [preview, setPreview] = useState<Awaited<
    ReturnType<typeof createDispatch.mutateAsync>
  > | null>(null)

  const effectiveVoice =
    voicePreset === "neutral" || voicePreset === "marvin"
      ? voicePreset
      : voicePreset === "custom"
        ? voiceText
        : voiceText

  const cliCommand = buildCliCommand({
    repo,
    org,
    scopeMode,
    since,
    until,
    branchScope,
    customBranches,
    generate,
    voice: effectiveVoice,
    format,
  })

  async function submit(dryRun: boolean) {
    const branches =
      branchScope === "all"
        ? "all"
        : branchScope === "custom"
          ? customBranches
              .split(",")
              .map((value) => value.trim())
              .filter(Boolean)
          : []

    const response = await createDispatch.mutateAsync({
      repo: scopeMode === "repo" ? repo : undefined,
      org: scopeMode === "org" ? org : undefined,
      since,
      until: until || new Date().toISOString(),
      branches: branches.length === 0 ? "all" : branches,
      generate,
      voice: effectiveVoice || undefined,
      dry_run: dryRun,
      format,
    })

    if (dryRun || !response.id) {
      startTransition(() => {
        setPreview(response)
      })
      return
    }

    navigate({
      to: "/dispatches/$dispatchId",
      params: { dispatchId: response.id },
    })
  }

  return (
    <Page title="New dispatch" pageTitle="New dispatch">
      <div className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_360px]">
        <form
          className="space-y-6"
          onSubmit={(event) => {
            event.preventDefault()
            void submit(false)
          }}
        >
          <section className="overflow-hidden rounded-[2rem] border border-subtle bg-base">
            <div className="border-b border-subtle bg-linear-to-br from-neutral-100 via-base to-neutral-200 px-6 py-5 dark:from-neutral-900 dark:via-base dark:to-neutral-950">
              <div className="font-mono text-[11px] uppercase tracking-[0.22em] text-muted">
                Scope
              </div>
              <h2 className="mt-3 text-xl font-semibold text-default">What should this cover?</h2>
            </div>
            <div className="grid gap-5 px-6 py-6">
              <div className="flex flex-wrap gap-2">
                {(["repo", "org"] as const).map((mode) => (
                  <button
                    key={mode}
                    type="button"
                    onClick={() => setScopeMode(mode)}
                    className={`rounded-full border px-4 py-2 text-sm transition-colors ${
