import { Skeleton } from "@/components/Skeleton"
import { Page } from "@/domains/platform/components/Page"
import { MarkdownContent } from "@/domains/platform/components/MarkdownContent"
import { Empty, EmptyDescription, EmptyTitle } from "@/components/Empty"

import { buildDispatchMarkdownFallback } from "../api"
import { DispatchSidebar } from "../components/DispatchSidebar"
import { useDispatchQuery } from "../hooks/useDispatch"

interface DispatchDetailPageProps {
  dispatchId: string
}

function buildCliCommand(dispatch: {
  covered_repos: string[]
  branches: string[] | "all"
  window: { normalized_since: string; normalized_until: string }
  voice: string | null
}) {
  const scopeFlag =
    dispatch.covered_repos.length === 1
      ? `--repo ${dispatch.covered_repos[0]}`
      : `--repos ${dispatch.covered_repos.join(",")}`
  const branchFlag =
    dispatch.branches === "all" ? "--branches all" : `--branches ${dispatch.branches.join(",")}`
  const voiceFlag = dispatch.voice ? ` --voice "${dispatch.voice}"` : ""

  return `entire dispatch ${scopeFlag} --since "${dispatch.window.normalized_since}" --until "${dispatch.window.normalized_until}" ${branchFlag}${voiceFlag}`.trim()
}

export function DispatchDetailPage({ dispatchId }: DispatchDetailPageProps) {
  const { data, isLoading, error } = useDispatchQuery(dispatchId)

  if (isLoading) {
    return (
      <Page title="Dispatch">
        <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_320px]">
          <Skeleton className="h-[32rem] rounded-3xl" />
          <Skeleton className="h-96 rounded-3xl" />
        </div>
      </Page>
    )
  }

  if (error || !data) {
    return (
      <Page title="Dispatch">
        <Empty fullHeight>
          <EmptyTitle>Dispatch unavailable</EmptyTitle>
          <EmptyDescription>
            {error?.message ?? "The dispatch could not be loaded."}
          </EmptyDescription>
        </Empty>
      </Page>
    )
  }

  const markdown = data.generated_markdown || buildDispatchMarkdownFallback(data)
  const cliCommand = buildCliCommand(data)

  return (
    <Page
      title={data.title}
      pageTitle={data.title}
      breadcrumbs={[
        { href: "/repositories", label: "Repositories" },
        { label: "Dispatch" },
      ]}
    >
      <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_320px]">
        <article className="overflow-hidden rounded-[2rem] border border-subtle bg-base">
          <div className="border-b border-subtle bg-linear-to-br from-neutral-100 via-base to-neutral-200 px-6 py-6 dark:from-neutral-900 dark:via-base dark:to-neutral-950">
            <div className="font-mono text-[11px] uppercase tracking-[0.22em] text-muted">
              Dispatch detail
            </div>
            <h1 className="mt-3 text-2xl font-semibold text-default">{data.title}</h1>
            <p className="mt-2 text-sm text-muted">
              {new Date(data.window.normalized_since).toLocaleDateString()} to{" "}
              {new Date(data.window.normalized_until).toLocaleDateString()} ·{" "}
              {data.totals.used_checkpoint_count} checkpoints · {data.totals.files_touched} files
            </p>
          </div>
          <div className="px-6 py-6">
            <MarkdownContent>{markdown}</MarkdownContent>
          </div>
        </article>

        <DispatchSidebar dispatch={data} cliCommand={cliCommand} />
      </div>
    </Page>
  )
}

