import { Hono } from "hono"
import { vi } from "vitest"

import type { Env } from "../env"
import { authApiRoutes, authOAuthRoutes } from "./auth"
import { authDevApiRoutes, authDevOAuthRoutes } from "./auth-dev"
import { preferencesApiRoutes } from "./preferences"

export function createMockKV() {
  const store = new Map<string, string>()
  return {
    get: vi.fn((key: string, type?: string) => {
      const value = store.get(key)
      if (value == null) return Promise.resolve(null)
      if (type === "json") {
        return Promise.resolve(JSON.parse(value))
      }
      return Promise.resolve(value)
    }),
    put: vi.fn((key: string, value: string) => {
      store.set(key, value)
      return Promise.resolve()
    }),
    delete: vi.fn((key: string) => {
      store.delete(key)
      return Promise.resolve()
    }),
    _store: store,
  }
}

export function createTestApp(
  kvOverride?: ReturnType<typeof createMockKV>,
  envOverrides?: Partial<Env>,
