import { Hono } from "hono"
import { describeRoute, resolver } from "hono-openapi"
import { getCookie, setCookie, deleteCookie } from "hono/cookie"
import { z } from "zod"

import { isAdmin, isLocalDev, type Env, type Variables } from "../env"
import { runInBackground } from "../lib/context"
import { encrypt } from "../lib/crypto"
import { getDb } from "../lib/db"
import type { Db } from "../lib/db/db-types"
import {
  exchangeCodeForToken,
  getGitHubUser,
  fetchUserInstallations,
  fetchInstallationRepos,
} from "../lib/github"
import { checkEntireOrgMembership } from "../lib/github-org-membership"
import { requireAuth } from "../lib/middleware"
import {
  getAllFeatureFlags,
  getOrCreatePostHogClient,
  revalidateFeatureFlagsIfStale,
  type PostHogPersonProperties,
} from "../lib/posthog"
import { createSession, getSession, deleteSession } from "../lib/session"
import { recordSpanError, traced } from "../lib/telemetry"
import { getValidGitHubTokenFromContext } from "../lib/token"
import { queueUserRepoSync, syncReposForUserWithToken } from "../lib/user-repo-sync"
import { getRepoPreferencesResponse } from "./preferences"

/** Compute feature_flags for an auth response. */
async function getAuthExtras(env: Env, userId: string, personProperties: PostHogPersonProperties) {
  const posthog = getOrCreatePostHogClient(env)

  const tFlags = Date.now()
  const featureFlags = await getAllFeatureFlags(posthog, userId, personProperties)
  const featureFlagsMs = Date.now() - tFlags

  return {
    posthog,
    featureFlags,
    timing: { featureFlagsMs },
  }
}

async function timed<T>(fn: () => Promise<T>): Promise<{ value: T; ms: number }> {
  const startedAt = Date.now()
  const value = await fn()
  return { value, ms: Date.now() - startedAt }
}

/**
 * Sync repos for a user with error handling and retry queuing.
 * Used by both OAuth and installation callbacks.
 */
async function syncReposWithRetry(
  db: Db,
  userId: string,
  githubLogin: string,
  token: string,
  env: Env,
  logPrefix: string,
): Promise<void> {
  try {
    const result = await syncReposForUserWithToken(db, userId, githubLogin, token, env)
    if (result.status === "error") {
      console.error(`${logPrefix}: repo sync failed for ${githubLogin}: ${result.reason}`)
      await queueUserRepoSync(env.USER_REPO_SYNC_QUEUE, userId, "retry", env.ENTIRE_CACHE)
    } else {
      console.log(`${logPrefix}: repo sync completed for user ${githubLogin}`)
    }
  } catch (err) {
    console.error(`${logPrefix}: repo sync failed for ${githubLogin}:`, err)
    await queueUserRepoSync(env.USER_REPO_SYNC_QUEUE, userId, "retry", env.ENTIRE_CACHE)
  }
}

// Helper: Get GitHub App installation URL with a secure nonce
async function generateGitHubInstallationUrl(env: Env, sessionToken: string): Promise<string> {
  // Use a short-lived nonce instead of the session token to avoid exposing it in URLs
  // URLs are logged in server logs, proxy logs, browser history, and Referer headers
