import { startTransition, useState } from "react"
import { useNavigate } from "@tanstack/react-router"

import { Badge } from "@/components/Badge"
import { Input } from "@/components"
import Button from "@/components/Button"
import Textarea from "@/components/Textarea"
import { Page } from "@/domains/platform/components/Page"

import {
  type DispatchBranchScope,
  type DispatchFormat,
  type DispatchVoicePreset,
} from "../api"
import { DispatchPreviewPane } from "../components/DispatchPreviewPane"
import { VoicePicker } from "../components/VoicePicker"
import { useCreateDispatchMutation } from "../hooks/useDispatch"

interface DispatchNewPageProps {
  initialRepo?: string
  initialOrg?: string
}

export function DispatchNewPage({ initialRepo = "", initialOrg = "" }: DispatchNewPageProps) {
  const navigate = useNavigate()
  const createDispatch = useCreateDispatchMutation()

  const [scopeMode, setScopeMode] = useState<"repo" | "org">(initialOrg ? "org" : "repo")
  const [repo, setRepo] = useState(initialRepo)
  const [org, setOrg] = useState(initialOrg)
  const [since, setSince] = useState("7d")
  const [until, setUntil] = useState("")
  const [branchScope, setBranchScope] = useState<DispatchBranchScope>("default")
  const [customBranches, setCustomBranches] = useState("")
  const [format, setFormat] = useState<DispatchFormat>("markdown")
  const [generate, setGenerate] = useState(true)
  const [voicePreset, setVoicePreset] = useState<DispatchVoicePreset>("neutral")
  const [voiceText, setVoiceText] = useState("")
  const [preview, setPreview] = useState<Awaited<
    ReturnType<typeof createDispatch.mutateAsync>
  > | null>(null)

  const effectiveVoice =
    voicePreset === "neutral" || voicePreset === "marvin"
      ? voicePreset
      : voicePreset === "custom"
        ? voiceText
        : voiceText

  async function submit(dryRun: boolean) {
    const branches =
      branchScope === "all"
        ? "all"
        : branchScope === "custom"
          ? customBranches
              .split(",")
              .map((value) => value.trim())
              .filter(Boolean)
          : []

    const response = await createDispatch.mutateAsync({
      repo: scopeMode === "repo" ? repo : undefined,
      org: scopeMode === "org" ? org : undefined,
      since,
      until: until || new Date().toISOString(),
      branches,
      generate,
      voice: effectiveVoice || undefined,
      dry_run: dryRun,
      format,
    })

    if (dryRun || !response.id) {
      startTransition(() => {
        setPreview(response)
      })
      return
    }

    navigate({
      to: "/dispatches/$dispatchId",
      params: { dispatchId: response.id },
    })
  }

  return (
    <Page title="New dispatch" pageTitle="New dispatch">
      <div className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_360px]">
        <form
          className="space-y-6"
          onSubmit={(event) => {
            event.preventDefault()
            void submit(false)
          }}
        >
          <section className="overflow-hidden rounded-[2rem] border border-subtle bg-base">
            <div className="border-b border-subtle bg-linear-to-br from-neutral-100 via-base to-neutral-200 px-6 py-5 dark:from-neutral-900 dark:via-base dark:to-neutral-950">
              <div className="font-mono text-[11px] uppercase tracking-[0.22em] text-muted">
                Scope
              </div>
              <h2 className="mt-3 text-xl font-semibold text-default">What should this cover?</h2>
            </div>
            <div className="grid gap-5 px-6 py-6">
              <div className="flex flex-wrap gap-2">
                {(["repo", "org"] as const).map((mode) => (
                  <button
                    key={mode}
                    type="button"
                    onClick={() => setScopeMode(mode)}
                    className={`rounded-full border px-4 py-2 text-sm transition-colors ${
                      scopeMode === mode
                        ? "border-neutral-900 bg-neutral-900 text-white dark:border-neutral-100 dark:bg-neutral-100 dark:text-neutral-900"
                        : "border-subtle bg-base text-default"
                    }`}
                  >
                    {mode === "repo" ? "Repos" : "Org"}
                  </button>
                ))}
              </div>

import { Hono } from "hono"

import type { Env, Variables } from "../env"
import { getDb } from "../lib/db"
import type { CheckpointWithCommit } from "../lib/db/checkpoints"
import type { AnalysisRow, Db } from "../lib/db/db-types"
import { requireAuth } from "../lib/middleware"
import type { ExtractionBlock, StoredCheckpointAnalysis } from "../types"
import { checkRepoAccess } from "./cache"

type DispatchStatus = "generating" | "complete" | "failed"
type DispatchBranches = string[] | "all"

interface DispatchWindow {
  normalized_since: string
  normalized_until: string
  first_checkpoint_created_at: string | null
  last_checkpoint_created_at: string | null
}

interface DispatchTotals {
  checkpoints: number
  used_checkpoint_count: number
  branches: number
  files_touched: number
}

interface DispatchWarnings {
  access_denied_count: number
  pending_count: number
  failed_count: number
  unknown_count: number
  uncategorized_count: number
}

interface DispatchBullet {
  checkpoint_id: string
  text: string
  source: "cloud_analysis" | "local_summary" | "commit_message"
  branch: string
  created_at: string
  labels: string[]
}

interface DispatchSection {
  label: string
  bullets: DispatchBullet[]
}

interface DispatchRepoGroup {
  full_name: string
  sections: DispatchSection[]
}

interface DispatchSummary {
  id: string
  title: string
  excerpt: string
  status: DispatchStatus
  covered_repos: string[]
  voice: string | null
  generated_at: string
  window: DispatchWindow
  totals: DispatchTotals
}

interface DispatchDetail extends DispatchSummary {
  fingerprint_hash: string | null
  branches: DispatchBranches
  web_url: string | null
  generated_markdown: string
  generated_text: string | null
  repos: DispatchRepoGroup[]
  warnings: DispatchWarnings
}

interface DispatchRecord extends DispatchDetail {
  user_id: string
  scope: {
    repo: string | null
    org: string | null
  }
  generated_text_search: string
}

interface CreateDispatchRequest {
  repo?: string
  org?: string
  since?: string
  until?: string
  branches?: DispatchBranches
  generate?: boolean
  voice?: string
  dry_run?: boolean
  format?: "markdown" | "text" | "json"
}

interface RepoDispatchData {
  fullName: string
  checkpoints: CheckpointWithCommit[]
  selectedBranches: string[]
  sections: DispatchSection[]
  warnings: DispatchWarnings
  usedCheckpointCount: number
  filesTouched: Set<string>
}

const DISPATCH_PREFIX = "dispatches:v1"

function dispatchDetailKey(id: string): string {
  return `${DISPATCH_PREFIX}:detail:${id}`
}

function dispatchUserIndexKey(userId: string): string {
  return `${DISPATCH_PREFIX}:user:${userId}:ids`
}

function emptyWarnings(): DispatchWarnings {
  return {
    access_denied_count: 0,
    pending_count: 0,
    failed_count: 0,
    unknown_count: 0,
    uncategorized_count: 0,
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null
}

function parseRelativeTime(value: string, now: Date): Date | null {
  const match = value.trim().match(/^(\d+)\s*([mhdw])$/i)
  if (!match) return null

  const amount = Number(match[1])
  const unit = match[2].toLowerCase()
  const minutes =
    unit === "m"
      ? amount
      : unit === "h"
        ? amount * 60
        : unit === "d"
          ? amount * 60 * 24
          : amount * 60 * 24 * 7

  return new Date(now.getTime() - minutes * 60 * 1000)
}

function parseTimeInput(value: string | undefined, fallback: Date): Date {
  const raw = value?.trim()
  if (!raw) return fallback

  const relative = parseRelativeTime(raw, fallback)
  if (relative) return relative

  const parsed = new Date(raw)
  if (!Number.isNaN(parsed.getTime())) return parsed

  return fallback
}

function normalizeWindow(since: string | undefined, until: string | undefined): DispatchWindow {
  const now = new Date()
  const normalizedUntil = parseTimeInput(until, now)
  const normalizedSince = parseTimeInput(
    since,
    new Date(normalizedUntil.getTime() - 7 * 24 * 60 * 60 * 1000),
  )

  return {
    normalized_since: normalizedSince.toISOString(),
    normalized_until: normalizedUntil.toISOString(),
    first_checkpoint_created_at: null,
    last_checkpoint_created_at: null,
  }
}

function isCheckpointInWindow(checkpoint: CheckpointWithCommit, window: DispatchWindow): boolean {
  const timestamp = checkpoint.created_at ?? checkpoint.commit_date
  if (!timestamp) return true

  const createdAt = new Date(timestamp).getTime()
  if (Number.isNaN(createdAt)) return true

  return (
    createdAt >= new Date(window.normalized_since).getTime() &&
    createdAt <= new Date(window.normalized_until).getTime()
  )
}

function parseStoredCheckpointAnalysis(analysisJson: string | null): StoredCheckpointAnalysis | null {
  if (!analysisJson) return null

  try {
    return JSON.parse(analysisJson) as StoredCheckpointAnalysis
  } catch {
    return null
  }
}

function blockSummary(block: ExtractionBlock): string | null {
  const candidates = [
    block.narrative,
    block.accepted,
    block.reasoning,
    block.keyFindings?.[0],
    block.openQuestions?.[0],
    block.title,
  ]

  for (const candidate of candidates) {
    if (typeof candidate === "string" && candidate.trim()) {
      return candidate.trim()
    }
  }

  return null
}

