// Token encryption utilities using Web Crypto API (AES-GCM)

const ALGORITHM = "AES-GCM"
const IV_LENGTH = 12 // 96 bits for GCM
const SALT_LENGTH = 16 // 128 bits (NIST recommended)
const LEGACY_SALT = "gh.social-salt" // For backward compatibility

// Base class for all decryption errors
export class DecryptionError extends Error {
  constructor(message: string) {
    super(message)
    this.name = "DecryptionError"
  }
}

// Auth tag verification failure - indicates tampering or wrong key
export class DecryptionAuthenticationError extends DecryptionError {
  constructor() {
    super("Decryption authentication failed")
    this.name = "DecryptionAuthenticationError"
  }
}

// Check if error is an auth tag verification failure
function isAuthTagFailure(error: unknown): boolean {
  // WebCrypto throws OperationError for auth tag failures
  return error instanceof DOMException && error.name === "OperationError"
}

// Derive a CryptoKey from a string secret and salt
async function deriveKey(secret: string, salt: Uint8Array): Promise<CryptoKey> {
  const encoder = new TextEncoder()
  const keyMaterial = await crypto.subtle.importKey(
    "raw",
    encoder.encode(secret),
    { name: "PBKDF2" },
    false,
    ["deriveKey"],
  )

  return crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt,
      iterations: 100000,
      hash: "SHA-256",
    },
    keyMaterial,
    { name: ALGORITHM, length: 256 },
    false,
    ["encrypt", "decrypt"],
  )
}

// Encrypt a plaintext string
// New format: base64(SALT[16] + IV[12] + ciphertext)
export async function encrypt(plaintext: string, secret: string): Promise<string> {
  const encoder = new TextEncoder()

  // Generate random salt for each encryption
  const salt = crypto.getRandomValues(new Uint8Array(SALT_LENGTH))
  const key = await deriveKey(secret, salt)
  const iv = crypto.getRandomValues(new Uint8Array(IV_LENGTH))

  const ciphertext = await crypto.subtle.encrypt(
    { name: ALGORITHM, iv },
    key,
    encoder.encode(plaintext),
  )

  // Combine SALT + IV + ciphertext and encode as base64
  const combined = new Uint8Array(salt.length + iv.length + ciphertext.byteLength)
  combined.set(salt)
  combined.set(iv, salt.length)
  combined.set(new Uint8Array(ciphertext), salt.length + iv.length)

  return btoa(String.fromCharCode(...combined))
}

// Decrypt a ciphertext string
// Supports both new format (SALT + IV + ciphertext) and legacy format (IV + ciphertext with static salt)
export async function decrypt(ciphertext: string, secret: string): Promise<string> {
  // Validate base64 first
  let combined: Uint8Array
  try {
    combined = Uint8Array.from(atob(ciphertext), (c) => c.charCodeAt(0))
  } catch {
    throw new DecryptionError("Invalid ciphertext format")
  }

  // Need minimum length for salt + IV
  if (combined.length < SALT_LENGTH + IV_LENGTH) {
    throw new DecryptionError("Invalid ciphertext format")
  }

  let lastError: unknown

  // Try new format first: SALT[16] + IV[12] + ciphertext
  try {
    const salt = combined.slice(0, SALT_LENGTH)
    const iv = combined.slice(SALT_LENGTH, SALT_LENGTH + IV_LENGTH)
    const data = combined.slice(SALT_LENGTH + IV_LENGTH)

    const key = await deriveKey(secret, salt)
    const plaintext = await crypto.subtle.decrypt({ name: ALGORITHM, iv }, key, data)

    return new TextDecoder().decode(plaintext)
  } catch (error) {
    lastError = error
  }

  // Fall back to legacy format: IV[12] + ciphertext with static salt
  try {
    const encoder = new TextEncoder()
    const legacySalt = encoder.encode(LEGACY_SALT)
    const iv = combined.slice(0, IV_LENGTH)
    const data = combined.slice(IV_LENGTH)

    const key = await deriveKey(secret, legacySalt)
    const plaintext = await crypto.subtle.decrypt({ name: ALGORITHM, iv }, key, data)

    return new TextDecoder().decode(plaintext)
  } catch (error) {
    lastError = error
  }

  // Both formats failed - determine error type
  if (isAuthTagFailure(lastError)) {
    throw new DecryptionAuthenticationError()
  }
  throw new DecryptionError("Decryption failed")
}

// Timing-safe string comparison using Web Crypto API
export async function timingSafeEqual(a: string, b: string): Promise<boolean> {
  const encoder = new TextEncoder()
  const aBytes = encoder.encode(a)
  const bBytes = encoder.encode(b)

  // timingSafeEqual requires equal lengths
  // For different lengths, do a dummy comparison to maintain constant timing, then return false
  if (aBytes.byteLength !== bBytes.byteLength) {
    await crypto.subtle.timingSafeEqual(aBytes, aBytes)
    return false
  }

  return crypto.subtle.timingSafeEqual(aBytes, bBytes)
}

// SHA-256 hash, returned as lowercase hex string (64 chars)
export async function sha256Hex(input: string): Promise<string> {
  const data = new TextEncoder().encode(input)
  const hashBuffer = await crypto.subtle.digest("SHA-256", data)
  return Array.from(new Uint8Array(hashBuffer))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("")
}

// API token prefix — identifies leaked tokens and enables secret scanning
export const API_TOKEN_PREFIX = "ent_"

// Generate a high-entropy API token (256 bits, URL-safe base64, prefixed)
export function generateApiToken(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(32))
  const payload = btoa(String.fromCharCode(...bytes))
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/, "")
  return API_TOKEN_PREFIX + payload
}

// Generate a secure random password
export function generateSecurePassword(length: number = 32): string {
  const chars = "REDACTED!@#$%^&*"
  const randomValues = crypto.getRandomValues(new Uint8Array(length))
  return Array.from(randomValues, (v) => chars[v % chars.length]).join("")
}

