import { Hono } from "hono"

import type { Env, Variables } from "../env"
import { sha256Hex } from "../lib/crypto"
import { getDb } from "../lib/db"
import type { CheckpointWithCommit } from "../lib/db/checkpoints"
import type { AnalysisRow, Db } from "../lib/db/db-types"
import { requireAuth } from "../lib/middleware"
import type { ExtractionBlock, StoredCheckpointAnalysis } from "../types"
import { checkRepoAccess } from "./cache"

type DispatchStatus = "generating" | "complete" | "failed"
type DispatchBranches = string[] | "all"

interface DispatchWindow {
  normalized_since: string
  normalized_until: string
  first_checkpoint_created_at: string | null
  last_checkpoint_created_at: string | null
}

interface DispatchTotals {
  checkpoints: number
  used_checkpoint_count: number
  branches: number
  files_touched: number
}

interface DispatchWarnings {
  access_denied_count: number
  pending_count: number
  failed_count: number
  unknown_count: number
  uncategorized_count: number
}

interface DispatchBullet {
  checkpoint_id: string
  text: string
  source: "cloud_analysis" | "local_summary" | "commit_message"
  branch: string
  created_at: string
  labels: string[]
}

interface DispatchSection {
  label: string
  bullets: DispatchBullet[]
}

interface DispatchRepoGroup {
  full_name: string
  sections: DispatchSection[]
}

interface DispatchSummary {
  id: string
  title: string
  excerpt: string
  status: DispatchStatus
  covered_repos: string[]
  voice: string | null
  generated_at: string
  window: DispatchWindow
  totals: DispatchTotals
}

interface DispatchDetail extends DispatchSummary {
  fingerprint_hash: string | null
  branches: DispatchBranches
  web_url: string | null
  generated_markdown: string
  generated_text: string | null
  repos: DispatchRepoGroup[]
  warnings: DispatchWarnings
}

interface DispatchRecord extends DispatchDetail {
  generated_text_search: string
  used_checkpoint_ids: string[]
}

interface CreateDispatchRequest {
  repo?: string
  org?: string
  since?: string
  until?: string
  branches?: DispatchBranches
  generate?: boolean
  voice?: string
  dry_run?: boolean
  format?: "markdown" | "text" | "json"
}

interface RepoDispatchData {
  fullName: string
  checkpoints: CheckpointWithCommit[]
  selectedBranches: string[]
  sections: DispatchSection[]
  warnings: DispatchWarnings
  usedCheckpointCount: number
  usedCheckpointIDs: Set<string>
  filesTouched: Set<string>
}

const DISPATCH_PREFIX = "dispatches:v1"

function dispatchDetailKey(id: string): string {
  return `${DISPATCH_PREFIX}:detail:${id}`
}

function dispatchRepoIndexKey(repoFullName: string): string {
  return `${DISPATCH_PREFIX}:repo:${repoFullName}:ids`
}

function dispatchOrgIndexKey(org: string): string {
  return `${DISPATCH_PREFIX}:org:${org}:ids`
}

function emptyWarnings(): DispatchWarnings {
  return {
    access_denied_count: 0,
    pending_count: 0,
    failed_count: 0,
    unknown_count: 0,
    uncategorized_count: 0,
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null
}

function parseRelativeTime(value: string, now: Date): Date | null {
  const match = value.trim().match(/^(\d+)\s*([mhdw])$/i)
  if (!match) return null

  const amount = Number(match[1])
  const unit = match[2].toLowerCase()
  const minutes =
    unit === "m"
      ? amount
      : unit === "h"
        ? amount * 60
        : unit === "d"
          ? amount * 60 * 24
          : amount * 60 * 24 * 7

  return new Date(now.getTime() - minutes * 60 * 1000)
}

function parseTimeInput(value: string | undefined, fallback: Date): Date {
  const raw = value?.trim()
  if (!raw) return fallback

  const relative = parseRelativeTime(raw, fallback)
  if (relative) return relative

  const parsed = new Date(raw)
  if (!Number.isNaN(parsed.getTime())) return parsed

  return fallback
}

function floorToMinute(value: Date): Date {
  return new Date(
    value.getFullYear(),
    value.getMonth(),
    value.getDate(),
    value.getHours(),
    value.getMinutes(),
    0,
    0,
  )
}

function ceilToMinute(value: Date): Date {
  const floored = floorToMinute(value)
  if (floored.getTime() === value.getTime()) {
    return floored
  }

  return new Date(floored.getTime() + 60 * 1000)
}

function normalizeWindow(since: string | undefined, until: string | undefined): DispatchWindow {
  const now = new Date()
  const normalizedUntil = ceilToMinute(parseTimeInput(until, now))
  const normalizedSince = floorToMinute(parseTimeInput(
    since,
    new Date(normalizedUntil.getTime() - 7 * 24 * 60 * 60 * 1000),
  ))

  return {
    normalized_since: normalizedSince.toISOString(),
    normalized_until: normalizedUntil.toISOString(),
    first_checkpoint_created_at: null,
    last_checkpoint_created_at: null,
  }
}

function isCheckpointInWindow(checkpoint: CheckpointWithCommit, window: DispatchWindow): boolean {
  const timestamp = checkpoint.created_at ?? checkpoint.commit_date
  if (!timestamp) return true

  const createdAt = new Date(timestamp).getTime()
  if (Number.isNaN(createdAt)) return true

  return (
    createdAt >= new Date(window.normalized_since).getTime() &&
    createdAt <= new Date(window.normalized_until).getTime()
  )
}

function parseStoredCheckpointAnalysis(analysisJson: string | null): StoredCheckpointAnalysis | null {
