	if shouldRunDispatchWizard(0, false, true) {
		t.Fatal("expected wizard not to run when stdin is piped")
	}
	if shouldRunDispatchWizard(1, true, true) {
		t.Fatal("expected wizard not to run when flags are provided")
	}
}

func TestDispatchInteractiveMode(t *testing.T) {
	t.Parallel()

	if got := dispatchInteractiveMode(0, true, true, false); got != dispatchInteractiveModeBubbleTea {
		t.Fatalf("expected bubbletea mode, got %v", got)
	}
	if got := dispatchInteractiveMode(0, true, true, true); got != dispatchInteractiveModeAccessible {
		t.Fatalf("expected accessible mode, got %v", got)
	}
	if got := dispatchInteractiveMode(1, true, true, false); got != dispatchInteractiveModeDisabled {
		t.Fatalf("expected interactive mode disabled when flags are set, got %v", got)
	}
	if got := dispatchInteractiveMode(0, false, true, false); got != dispatchInteractiveModeDisabled {
		t.Fatalf("expected interactive mode disabled when stdin is piped, got %v", got)
	}
	if got := dispatchInteractiveMode(0, true, false, false); got != dispatchInteractiveModeDisabled {
		t.Fatalf("expected interactive mode disabled when stdout is not a terminal, got %v", got)
	}
}

func TestDispatchWizardGenerateDefault(t *testing.T) {
	t.Parallel()

	if !dispatchWizardGenerateDefault {
