package cli

import (
	"testing"

	tea "github.com/charmbracelet/bubbletea"
	dispatchpkg "github.com/entireio/cli/cmd/entire/cli/dispatch"
)

func testDispatchTUIModel() dispatchTUIModel {
	return newDispatchTUIModel(
		statusStyles{width: 120, colorEnabled: false},
		func() (string, error) { return "feature/preview", nil },
	)
}

func updateDispatchTUIModel(t *testing.T, m dispatchTUIModel, msg tea.Msg) dispatchTUIModel {
	t.Helper()
	updated, _ := m.Update(msg)
	next, ok := updated.(dispatchTUIModel)
	if !ok {
		t.Fatalf("Update returned %T, want dispatchTUIModel", updated)
	}
	return next
}

func TestDispatchTUIModel_DefaultPreviewUsesCurrentBranch(t *testing.T) {
	t.Parallel()

	preview := testDispatchTUIModel().preview()
	if preview.ValidationError != "" {
		t.Fatalf("expected no validation error, got %q", preview.ValidationError)
	}
	if preview.EffectiveBranches != "feature/preview" {
		t.Fatalf("expected current branch preview, got %q", preview.EffectiveBranches)
	}
	if preview.Command == "" {
		t.Fatal("expected command preview")
	}
}

func REDACTED(t *testing.T) {
	t.Parallel()

	m := testDispatchTUIModel()
	m.orgInput.SetValue("entireio")

	preview := m.preview()
	if preview.ValidationError != "" {
		t.Fatalf("expected no validation error, got %q", preview.ValidationError)
	}
	if preview.EffectiveBranches != "all" {
		t.Fatalf("expected org mode to preview all branches, got %q", preview.EffectiveBranches)
	}
	if preview.Command == "" || preview.Command == "entire dispatch" {
		t.Fatalf("expected command preview to include org scope, got %q", preview.Command)
	}
}

func TestDispatchTUIModel_ServerReposValidation(t *testing.T) {
	t.Parallel()

	m := testDispatchTUIModel()
	m.reposInput.SetValue("/tmp/repo-a,/tmp/repo-b")

	preview := m.preview()
	if preview.ValidationError == "" {
		t.Fatal("expected validation error for repos without local mode")
	}
}

func TestDispatchTUIModel_SubmitReturnsResolvedOptions(t *testing.T) {
	t.Parallel()

	m := testDispatchTUIModel()
	m.sourceMode = dispatchTUISourceModeLocal
	m.reposInput.SetValue("/tmp/repo-a,/tmp/repo-b")
	m.generate = false
	m.format = "markdown"

	m = updateDispatchTUIModel(t, m, tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'r'}})
	if !m.submitted {
		t.Fatal("expected model to submit")
	}
	if m.cancelled {
		t.Fatal("expected submit not to cancel")
	}
	if m.submittedOpts.Mode != dispatchpkg.ModeLocal {
		t.Fatalf("expected local mode, got %v", m.submittedOpts.Mode)
	}
	if len(m.submittedOpts.RepoPaths) != 2 {
		t.Fatalf("expected two repo paths, got %v", m.submittedOpts.RepoPaths)
	}
	if m.submittedOpts.Generate {
		t.Fatal("expected generate=false to be preserved")
	}
	if m.submittedOpts.Format != "markdown" {
		t.Fatalf("expected markdown format, got %q", m.submittedOpts.Format)
	}
}

func TestDispatchTUIModel_QuitCancels(t *testing.T) {
	t.Parallel()

	m := updateDispatchTUIModel(t, testDispatchTUIModel(), tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'q'}})
	if !m.cancelled {
		t.Fatal("expected cancel state")
	}
	if m.submitted {
		t.Fatal("did not expect submit state")
	}
}

