package cli

import (
	"errors"
	"fmt"
	"strings"

	"github.com/charmbracelet/huh"
	dispatchpkg "github.com/entireio/cli/cmd/entire/cli/dispatch"
	"github.com/spf13/cobra"
)

var errDispatchCancelled = errors.New("dispatch cancelled")

type dispatchWizardState struct {
	modeChoice    string
	since         string
	until         string
	branchScope   string
	customBranches string
	org           string
	reposCSV      string
	generate      bool
	voice         string
	format        string
	dryRun        bool
	wait          bool
	confirmRun    bool
}

func newDispatchWizardState() dispatchWizardState {
	return dispatchWizardState{
		modeChoice:  "server",
		since:       "7d",
		branchScope: "default",
		generate:    dispatchWizardGenerateDefault,
		format:      "text",
	}
}

func (s dispatchWizardState) isLocal() bool {
	return s.modeChoice == "local"
}

func (s dispatchWizardState) branchesFlag() string {
	switch s.branchScope {
	case "all":
		return "all"
	case "custom":
		return strings.TrimSpace(s.customBranches)
	default:
		return ""
	}
}

func (s dispatchWizardState) resolve(currentBranch func() (string, error)) (dispatchpkg.Options, error) {
	return resolveDispatchOptions(
		s.isLocal(),
		s.since,
		s.until,
		s.branchesFlag(),
		splitCSVField(s.reposCSV),
		strings.TrimSpace(s.org),
		s.generate,
		strings.TrimSpace(s.voice),
		s.format,
		s.dryRun,
		s.wait,
		currentBranch,
	)
}

func buildDispatchWizardSummary(opts dispatchpkg.Options) string {
	scope := "current repo"
	switch {
	case strings.TrimSpace(opts.Org) != "":
		scope = "org:" + strings.TrimSpace(opts.Org)
	case len(opts.RepoPaths) > 0:
		scope = "repos:" + strings.Join(opts.RepoPaths, ", ")
	}

	branches := "current branch"
	if opts.AllBranches {
		branches = "all"
	} else if len(opts.Branches) > 0 {
		branches = strings.Join(opts.Branches, ", ")
	}

	mode := "server"
	if opts.Mode == dispatchpkg.ModeLocal {
		mode = "local"
	}

	return strings.Join([]string{
		"Mode: " + mode,
		"Scope: " + scope,
		"Branches: " + branches,
	}, "\n")
}

func buildDispatchCommand(opts dispatchpkg.Options) string {
	branchesValue := ""
	if opts.AllBranches {
		branchesValue = "all"
	} else if len(opts.Branches) > 0 {
		branchesValue = strings.Join(opts.Branches, ",")
	}

	return strings.Join(compactStrings([]string{
		"entire dispatch",
		mapBoolToFlag(opts.Mode == dispatchpkg.ModeLocal, "--local"),
		renderStringFlag("--since", strings.TrimSpace(opts.Since)),
		renderStringFlag("--until", strings.TrimSpace(opts.Until)),
		renderStringFlag("--branches", branchesValue),
		renderStringFlag("--repos", strings.Join(opts.RepoPaths, ",")),
		renderStringFlag("--org", strings.TrimSpace(opts.Org)),
		mapBoolToFlag(opts.Generate, "--generate"),
		renderStringFlag("--voice", strings.TrimSpace(opts.Voice)),
		renderStringFlag("--format", strings.TrimSpace(opts.Format)),
		mapBoolToFlag(opts.DryRun, "--dry-run"),
		mapBoolToFlag(opts.Wait, "--wait"),
	}), " ")
}

func splitCSVField(value string) []string {
	if strings.TrimSpace(value) == "" {
		return nil
	}
	parts := strings.Split(value, ",")
	result := make([]string, 0, len(parts))
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part != "" {
			result = append(result, part)
		}
	}
	return result
}

func compactStrings(values []string) []string {
	result := make([]string, 0, len(values))
	for _, value := range values {
		if value != "" {
			result = append(result, value)
		}
	}
	return result
}

func mapBoolToFlag(enabled bool, flag string) string {
	if enabled {
		return flag
	}
	return ""
}

func renderStringFlag(name string, value string) string {
	if value == "" {
		return ""
	}
	return name + " " + quoteShellValue(value)
}

func quoteShellValue(value string) string {
	if value == "" {
		return `""`
	}
	if strings.ContainsAny(value, " ,:\t") {
		return fmt.Sprintf("%q", value)
	}
	return value
}

func runDispatchWizard(cmd *cobra.Command) (dispatchpkg.Options, error) {
	state := newDispatchWizardState()
	currentBranch := func() (string, error) {
		return GetCurrentBranch(cmd.Context())
	}

	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Dispatch mode").
				Options(
					huh.NewOption("Server", "server"),
					huh.NewOption("Local", "local"),
				).
				Value(&state.modeChoice),
			huh.NewInput().
				Title("Organization").
				Description("Leave blank to use the current repo or local repo list.").
				Value(&state.org).
				Validate(func(value string) error {
					if strings.TrimSpace(value) != "" && strings.TrimSpace(state.reposCSV) != "" {
						return errors.New("org and repos are mutually exclusive")
					}
					return nil
				}),
			huh.NewInput().
				Title("Repos").
				Description("Comma-separated local repo paths. Requires local mode.").
				Value(&state.reposCSV).
				Validate(func(value string) error {
					if strings.TrimSpace(value) == "" {
						return nil
					}
					if !state.isLocal() {
						return errors.New("repos requires local mode")
					}
					if strings.TrimSpace(state.org) != "" {
						return errors.New("repos and org are mutually exclusive")
					}
					return nil
				}),
		).Title("Scope").Description("Choose where the dispatch should pull from."),
		huh.NewGroup(
			huh.NewInput().
				Title("Since").
				Description("Examples: 7d, 2 days ago, 2026-04-09").
				Value(&state.since),
			huh.NewInput().
				Title("Until").
				Description("Optional end time. Leave blank for now.").
				Value(&state.until),
			huh.NewSelect[string]().
				Title("Branch scope").
				Options(
					huh.NewOption("Default", "default"),
					huh.NewOption("All", "all"),
					huh.NewOption("Custom", "custom"),
				).
				Value(&state.branchScope),
			huh.NewInput().
				Title("Custom branches").
				Description("Comma-separated branch names. Used only for custom branch scope.").
				Value(&state.customBranches).
				Validate(func(value string) error {
					if state.branchScope == "custom" && strings.TrimSpace(value) == "" {
						return errors.New("enter at least one branch")
					}
					return nil
				}),
		).Title("Window").Description("Set the time window and branch selection."),
		huh.NewGroup(
			huh.NewConfirm().
				Title("Generate prose?").
				Value(&state.generate),
			huh.NewInput().
				Title("Voice").
				Description("Preset name, file path, or literal guidance. Leave blank for neutral.").
				Value(&state.voice),
			huh.NewSelect[string]().
				Title("Format").
				Options(
					huh.NewOption("Text", "text"),
					huh.NewOption("Markdown", "markdown"),
					huh.NewOption("JSON", "json"),
				).
				Value(&state.format),
			huh.NewConfirm().
				Title("Dry run?").
				Value(&state.dryRun),
			huh.NewConfirm().
				Title("Wait for pending analyses?").
				Value(&state.wait),
		).Title("Output").Description("Choose generation and output settings."),
		huh.NewGroup(
			huh.NewNote().
				Title("Resolved options").
				DescriptionFunc(func() string {
					opts, err := state.resolve(currentBranch)
					if err != nil {
						return "Validation error: " + err.Error()
					}
					return buildDispatchWizardSummary(opts)
				}, &state),
			huh.NewNote().
				Title("Command").
				DescriptionFunc(func() string {
					opts, err := state.resolve(currentBranch)
					if err != nil {
						return "Validation error: " + err.Error()
					}
					return buildDispatchCommand(opts)
				}, &state),
			huh.NewConfirm().
				Title("Run dispatch?").
				Affirmative("Run").
				Negative("Cancel").
				Value(&state.confirmRun),
		).Title("Confirm").Description("Review the resolved command and run it."),
	)

	if err := form.Run(); err != nil {
		if handled := handleFormCancellation(cmd.OutOrStdout(), "dispatch", err); handled == nil {
			return dispatchpkg.Options{}, errDispatchCancelled
		}
		return dispatchpkg.Options{}, err
	}
	if !state.confirmRun {
		fmt.Fprintln(cmd.OutOrStdout(), "dispatch cancelled.")
		return dispatchpkg.Options{}, errDispatchCancelled
	}

	return state.resolve(currentBranch)
}

