package dispatch

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"time"
)

var (
	goDurationPattern  = regexp.MustCompile(`^(\d+)([smhdw])$`)
	relativePattern    = regexp.MustCompile(`^(\d+)\s*(second|minute|hour|day|week|month)s?(?:\s*ago)?$`)
	lastWeekdayPattern = regexp.MustCompile(`^last\s+(monday|tuesday|wednesday|thursday|friday|saturday|sunday)$`)
)

// ParseSinceAtNow parses durations like 7d, relative times like "2 days ago",
// RFC3339 timestamps, and ISO dates.
func ParseSinceAtNow(value string, now time.Time) (time.Time, error) {
	parsed, err := parseTimeAtNow(value, now)
	if err != nil {
		return time.Time{}, err
	}
	if parsed.IsZero() {
		return time.Time{}, fmt.Errorf("unparseable --since: %q", strings.TrimSpace(value))
	}
	return parsed, nil
}

func ParseUntilAtNow(value string, now time.Time) (time.Time, error) {
	parsed, err := parseTimeAtNow(value, now)
	if err != nil {
		return time.Time{}, err
	}
	if parsed.IsZero() {
		return now, nil
	}
	return parsed, nil
}

func parseTimeAtNow(value string, now time.Time) (time.Time, error) {
	value = strings.TrimSpace(value)
	if value == "" {
		return time.Time{}, nil
	}
	if strings.EqualFold(value, "now") {
		return now, nil
	}

	if matches := goDurationPattern.FindStringSubmatch(value); matches != nil {
		n, err := strconv.Atoi(matches[1])
		if err != nil {
			return time.Time{}, fmt.Errorf("parse duration count: %w", err)
		}
		switch matches[2] {
		case "d":
			return now.Add(-time.Duration(n) * 24 * time.Hour), nil
		case "w":
			return now.Add(-time.Duration(n) * 7 * 24 * time.Hour), nil
		default:
			d, err := time.ParseDuration(matches[1] + matches[2])
			if err != nil {
				return time.Time{}, fmt.Errorf("parse duration: %w", err)
			}
			return now.Add(-d), nil
		}
	}

	if matches := relativePattern.FindStringSubmatch(strings.ToLower(value)); matches != nil {
		n, err := strconv.Atoi(matches[1])
		if err != nil {
			return time.Time{}, fmt.Errorf("parse relative count: %w", err)
		}
		var unit time.Duration
		switch matches[2] {
		case "second":
			unit = time.Second
		case "minute":
			unit = time.Minute
		case "hour":
			unit = time.Hour
		case "day":
			unit = 24 * time.Hour
		case "week":
			unit = 7 * 24 * time.Hour
		case "month":
			unit = 30 * 24 * time.Hour
		}
		return now.Add(-time.Duration(n) * unit), nil
	}

	if matches := lastWeekdayPattern.FindStringSubmatch(strings.ToLower(value)); matches != nil {
		target := weekdayFromString(matches[1])
		if target >= 0 {
			diff := (int(now.Weekday()) - int(target) + 7) % 7
			if diff == 0 {
				diff = 7
			}
			return now.Add(-time.Duration(diff) * 24 * time.Hour), nil
		}
	}

	if parsed, err := time.Parse(time.RFC3339, value); err == nil {
		return parsed, nil
	}
	if parsed, err := time.Parse("2006-01-02", value); err == nil {
		return parsed, nil
	}

	return time.Time{}, fmt.Errorf("unparseable time: %q", value)
}

func weekdayFromString(value string) time.Weekday {
	switch value {
	case "sunday":
		return time.Sunday
	case "monday":
		return time.Monday
	case "tuesday":
		return time.Tuesday
	case "wednesday":
		return time.Wednesday
	case "thursday":
		return time.Thursday
	case "friday":
		return time.Friday
	case "saturday":
		return time.Saturday
	default:
		return -1
	}
}

func ParseBranches(value string, currentBranch string) ([]string, bool, error) {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "":
		return []string{currentBranch}, false, nil
	case "all", "*":
		return nil, true, nil
	}

	parts := strings.Split(value, ",")
	out := make([]string, 0, len(parts))
	for _, part := range parts {
		trimmed := strings.TrimSpace(part)
		if trimmed == "" {
			continue
		}
		out = append(out, trimmed)
	}
	if len(out) == 0 {
		return nil, false, fmt.Errorf("no branch names provided")
	}
	return out, false, nil
}

package dispatch

import (
	"testing"
	"time"
)

func TestParseSince_GoDuration(t *testing.T) {
	t.Parallel()

	now := time.Date(2026, 4, 16, 14, 32, 0, 0, time.UTC)
	got, err := ParseSinceAtNow("7d", now)
	if err != nil {
		t.Fatal(err)
	}
	want := now.Add(-7 * 24 * time.Hour)
	if !got.Equal(want) {
		t.Fatalf("want %v got %v", want, got)
	}
}

func TestParseSince_GitStyle(t *testing.T) {
	t.Parallel()

	now := time.Date(2026, 4, 16, 12, 0, 0, 0, time.UTC)
	got, err := ParseSinceAtNow("2 days ago", now)
	if err != nil {
		t.Fatal(err)
	}
	if !got.Equal(now.Add(-48 * time.Hour)) {
		t.Fatalf("got %v", got)
	}
}

func TestParseSince_GitStyleWithoutAgo(t *testing.T) {
	t.Parallel()

	now := time.Date(2026, 4, 16, 12, 0, 0, 0, time.UTC)
	got, err := ParseSinceAtNow("1 week", now)
	if err != nil {
		t.Fatal(err)
	}
	if !got.Equal(now.Add(-7 * 24 * time.Hour)) {
		t.Fatalf("got %v", got)
	}
}

func TestParseSince_LastWeekday(t *testing.T) {
	t.Parallel()

	now := time.Date(2026, 4, 16, 12, 0, 0, 0, time.UTC)
	got, err := ParseSinceAtNow("last monday", now)
	if err != nil {
		t.Fatal(err)
	}
	want := time.Date(2026, 4, 13, 12, 0, 0, 0, time.UTC)
	if !got.Equal(want) {
		t.Fatalf("want %v got %v", want, got)
	}
}

func TestParseSince_ISO(t *testing.T) {
	t.Parallel()

	got, err := ParseSinceAtNow("2026-04-09", time.Now())
	if err != nil {
		t.Fatal(err)
	}
	if got.Year() != 2026 || got.Month() != 4 || got.Day() != 9 {
		t.Fatalf("got %v", got)
	}
}

func TestParseBranches_List(t *testing.T) {
	t.Parallel()

	b, allBranches, err := ParseBranches("main,release", "main")
	if err != nil {
		t.Fatal(err)
	}
	if allBranches {
		t.Fatal("all should be false")
	}
	if len(b) != 2 || b[0] != "main" || b[1] != "release" {
		t.Fatalf("got %v", b)
	}
}

func TestParseBranches_All(t *testing.T) {
	t.Parallel()

	b, allBranches, err := ParseBranches("all", "main")
	if err != nil {
		t.Fatal(err)
	}
	if !allBranches {
		t.Fatal("all should be true")
	}
	if b != nil {
		t.Fatalf("expected nil slice, got %v", b)
	}
}

func TestParseBranches_Default(t *testing.T) {
	t.Parallel()

	b, allBranches, err := ParseBranches("", "feat/x")
	if err != nil {
		t.Fatal(err)
	}
	if allBranches {
		t.Fatal("all should be false")
	}
	if len(b) != 1 || b[0] != "feat/x" {
		t.Fatalf("got %v", b)
	}
}

func TestParseUntil_EmptyDefaultsToNow(t *testing.T) {
	t.Parallel()

	now := time.Date(2026, 4, 16, 14, 32, 0, 0, time.UTC)
	got, err := ParseUntilAtNow("", now)
	if err != nil {
		t.Fatal(err)
	}
	if !got.Equal(now) {
		t.Fatalf("want %v got %v", now, got)
	}
}

