	})

	t.Setenv("ENTIRE_API_BASE_URL", mock.URL)
	t.Chdir(dir)

	got, err := Run(context.Background(), Options{
		Mode:     ModeServer,
		Since:    "7d",
		Until:    "2026-04-15T18:30:00Z",
		Branches: []string{"main"},
		Generate: true,
		Voice:    "neutral",
		DryRun:   true,
		Format:   "text",
	})
	if err != nil {
		t.Fatal(err)
	}
	if got.ID != "dsp_abc" {
		t.Fatalf("bad id: %v", got.ID)
	}
	if got.GeneratedText != "Hello" {
		t.Fatalf("bad text: %q", got.GeneratedText)
	}
	if !got.DryRun {
		t.Fatal("expected dry run flag to propagate")
	}
	if !got.RequestedGenerate {
		t.Fatal("expected requested generate flag to propagate")
	}
}

