var errDispatchCancelled = errors.New("dispatch cancelled")
var wizardNowUTC = func() time.Time { return time.Now().UTC() }

type dispatchWizardState struct {
	modeChoice       string
	timeWindowPreset string
	until            string
	branchScope      string
	customBranches   string
