package dispatch

import (
	"context"
	"errors"
)

type Mode int

const (
	ModeServer Mode = iota
	ModeLocal
)

// Options holds all parsed CLI inputs.
type Options struct {
	Mode        Mode
	RepoPaths   []string
	Org         string
	Since       string
	Until       string
	Branches    []string
	AllBranches bool
	Generate    bool
	Voice       string
	Format      string
	DryRun      bool
	Wait        bool
