package cli

import (
	"strings"
	"testing"
	"time"

	dispatchpkg "github.com/entireio/cli/cmd/entire/cli/dispatch"
)

func TestNewDispatchWizardState_Defaults(t *testing.T) {
	t.Parallel()

	oldNow := wizardNowUTC
	wizardNowUTC = func() time.Time { return time.Date(2026, 4, 17, 9, 30, 0, 0, time.UTC) }
	t.Cleanup(func() {
		wizardNowUTC = oldNow
	})

	state := newDispatchWizardState()
	if state.timeWindowPreset != "7d" {
		t.Fatalf("expected 7d default, got %q", state.timeWindowPreset)
	}
	if state.until != "2026-04-17" {
		t.Fatalf("expected today's date default, got %q", state.until)
	}
	if state.branchScope != "current" {
		t.Fatalf("expected current branch default, got %q", state.branchScope)
	}
	if state.voiceMode != "neutral" {
		t.Fatalf("expected neutral voice mode, got %q", state.voiceMode)
	}
}

func TestDispatchWizardState_ResolveOrgDefaultsToAllBranches(t *testing.T) {
	t.Parallel()

	state := newDispatchWizardState()
	state.org = "entireio"

	opts, err := state.resolve(func() (string, error) { return "feature/preview", nil })
	if err != nil {
		t.Fatal(err)
	}
	if !opts.AllBranches {
		t.Fatal("expected org scope to default to all branches")
	}
	if opts.Branches != nil {
		t.Fatalf("expected nil branches, got %v", opts.Branches)
	}
}

func TestDispatchWizardState_ResolveReposRequireLocal(t *testing.T) {
	t.Parallel()

	state := newDispatchWizardState()
	state.reposCSV = "/tmp/repo-a,/tmp/repo-b"

	_, err := state.resolve(func() (string, error) { return "feature/preview", nil })
	if err == nil {
		t.Fatal("expected repos to require local mode")
	}
}

func TestDispatchWizardState_ResolveVoiceModes(t *testing.T) {
	t.Parallel()

	state := newDispatchWizardState()
	state.voiceMode = "marvin"
	opts, err := state.resolve(func() (string, error) { return "feature/preview", nil })
	if err != nil {
		t.Fatal(err)
	}
	if opts.Voice != "marvin" {
		t.Fatalf("expected marvin voice, got %q", opts.Voice)
	}

	state.voiceMode = "custom"
	state.customVoice = "~/voice.md"
	opts, err = state.resolve(func() (string, error) { return "feature/preview", nil })
	if err != nil {
		t.Fatal(err)
	}
	if opts.Voice != "~/voice.md" {
		t.Fatalf("expected custom voice, got %q", opts.Voice)
	}
}

func TestBuildDispatchWizardSummary(t *testing.T) {
	t.Parallel()

	summary := buildDispatchWizardSummary(dispatchpkg.Options{
		Mode:        dispatchpkg.ModeLocal,
		RepoPaths:   []string{"/tmp/repo-a", "/tmp/repo-b"},
		Branches:    []string{"main", "release"},
		AllBranches: false,
	})
	if !strings.Contains(summary, "Mode: local") {
		t.Fatalf("expected local mode in summary, got %q", summary)
	}
	if !strings.Contains(summary, "Scope: repos:/tmp/repo-a, /tmp/repo-b") {
		t.Fatalf("expected repo scope in summary, got %q", summary)
	}
	if !strings.Contains(summary, "Branches: main, release") {
		t.Fatalf("expected branches in summary, got %q", summary)
	}
}

