+	branchesByRepo := make(map[string][]huh.Option[string], len(repoRoots))
+	orgSet := make(map[string]struct{})
+	for _, repoRoot := range repoRoots {
+		label := filepath.Base(repoRoot)
+		if repoRoot == currentRepo {
+			label += " (current)"
+		}
+		repoOptions = append(repoOptions, huh.NewOption(label, repoRoot))
+		branchesByRepo[repoRoot] = discoverBranchOptions(ctx, repoRoot)
+		if org := discoverRepoOrg(repoRoot); org != "" {
+			orgSet[org] = struct{}{}
+		}
+	}
+
+	orgNames := make([]string, 0, len(orgSet))
+	for org := range orgSet {
+		orgNames = append(orgNames, org)
+	}
+	sort.Strings(orgNames)
+
+	orgOptions := make([]huh.Option[string], 0, len(orgNames))
+	for _, org := range orgNames {
+		orgOptions = append(orgOptions, huh.NewOption(org, org))
+	}
+
