	dispatchWizardScopeSelectedRepos = "selected_repos"
	dispatchWizardScopeOrganization  = "organization"

	dispatchWizardBranchCurrent  = "current"
	dispatchWizardBranchAll      = "all"
	dispatchWizardBranchSelected = "selected"
