func NewCloudClient(cfg CloudConfig) *CloudClient {
	baseURL := cfg.BaseURL
	if baseURL == "" {
		baseURL = api.BaseURL()
	}

	timeout := cfg.Timeout
	if timeout == 0 {
		timeout = cloudTimeout
	}

	httpClient := cfg.HTTP
	if httpClient == nil {
