func resolveRepoRoots(ctx context.Context, repoPaths []string) ([]string, error) {
	if len(repoPaths) == 0 {
		repoRoot, err := paths.WorktreeRoot(ctx)
		if err != nil {
			return nil, fmt.Errorf("not in a git repository: %w", err)
