package dispatch

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/go-git/go-git/v6"
)

func runServer(ctx context.Context, opts Options) (*Dispatch, error) {
	token, err := lookupCurrentToken()
	if err != nil {
		return nil, fmt.Errorf("reading credentials: %w", err)
	}
	if token == "" {
		return nil, fmt.Errorf("dispatch requires login — run `entire login`")
	}

	now := nowUTC()
	sinceInput := strings.TrimSpace(opts.Since)
	if sinceInput == "" {
		sinceInput = "7d"
	}
	since, err := ParseSinceAtNow(sinceInput, now)
	if err != nil {
		return nil, err
	}
	until, err := ParseUntilAtNow(opts.Until, now)
	if err != nil {
		return nil, err
	}
	if !since.Before(until) {
		return nil, fmt.Errorf("--since must be before --until")
	}

	repoFullName := ""
	repoFullNames := append([]string(nil), opts.RepoPaths...)
	if opts.Org == "" && len(repoFullNames) == 0 {
		repoRoot, err := paths.WorktreeRoot(ctx)
		if err != nil {
			return nil, fmt.Errorf("not in a git repository: %w", err)
		}
		repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
		if err != nil {
			return nil, fmt.Errorf("open repository: %w", err)
		}
		repoFullName, err = resolveRepoFullName(repo)
		if err != nil {
			return nil, err
		}
		repoFullNames = []string{repoFullName}
	}

	branches := any(opts.Branches)
	if opts.AllBranches {
		branches = "all"
	}

	cloud := NewCloudClient(CloudConfig{BaseURL: cloudBaseURL(), Token: token})
	reqBody := CreateDispatchRequest{
		Repo:     repoFullName,
		Repos:    repoFullNames,
		Org:      opts.Org,
		Since:    since.Format(time.RFC3339),
		Until:    until.Format(time.RFC3339),
		Branches: branches,
		Generate: opts.Generate,
		Voice:    opts.Voice,
		Wait:     opts.Wait,
	}
	if len(repoFullNames) > 0 {
		reqBody.Repo = ""
	}
	response, err := cloud.CreateDispatch(ctx, reqBody)
	if err != nil {
		return nil, err
	}

	dispatch := apiToDispatch(response)
	dispatch.RequestedGenerate = opts.Generate
	return dispatch, nil
}

func apiToDispatch(response *CreateDispatchResponse) *Dispatch {
	if response == nil {
		return &Dispatch{}
	}

	repos := make([]RepoGroup, 0, len(response.Repos))
	for _, repo := range response.Repos {
		sections := make([]Section, 0, len(repo.Sections))
		for _, section := range repo.Sections {
			bullets := make([]Bullet, 0, len(section.Bullets))
			for _, bullet := range section.Bullets {
				bullets = append(bullets, Bullet{
					CheckpointID: bullet.CheckpointID,
					Text:         bullet.Text,
					Source:       bullet.Source,
					Branch:       bullet.Branch,
					CreatedAt:    parseAPITime(bullet.CreatedAt),
					Labels:       append([]string(nil), bullet.Labels...),
				})
			}
			sections = append(sections, Section{
				Label:   section.Label,
				Bullets: bullets,
			})
		}
		repos = append(repos, RepoGroup{
			FullName: repo.FullName,
			Sections: sections,
		})
	}

	return &Dispatch{
		Window: Window{
			NormalizedSince:   parseAPITime(response.Window.NormalizedSince),

		scope = "repos:" + strings.Join(opts.RepoPaths, ", ")
	}

	branches := "current branch"
	if opts.AllBranches {
		branches = "all"
	} else if len(opts.Branches) > 0 {
		branches = strings.Join(opts.Branches, ", ")
	}

	mode := "server"
	if opts.Mode == dispatchpkg.ModeLocal {
		mode = "local"
	}

	return strings.Join([]string{
		"Mode: " + mode,
		"Scope: " + scope,
		"Branches: " + branches,
	}, "\n")
}

func buildDispatchCommand(opts dispatchpkg.Options) string {
	branchesValue := ""
	if opts.AllBranches {
		branchesValue = "all"
	} else if len(opts.Branches) > 0 {
		branchesValue = strings.Join(opts.Branches, ",")
	}

	return strings.Join(compactStrings([]string{
		"entire dispatch",
		mapBoolToFlag(opts.Mode == dispatchpkg.ModeLocal, "--local"),
		renderStringFlag("--since", strings.TrimSpace(opts.Since)),
		renderStringFlag("--branches", branchesValue),
		renderStringFlag("--repos", strings.Join(opts.RepoPaths, ",")),
		renderStringFlag("--org", strings.TrimSpace(opts.Org)),
		mapBoolToFlag(opts.Generate, "--generate"),
		renderStringFlag("--voice", strings.TrimSpace(opts.Voice)),
		renderStringFlag("--format", strings.TrimSpace(opts.Format)),
		mapBoolToFlag(opts.Wait, "--wait"),
	}), " ")
}

func compactStrings(values []string) []string {
	result := make([]string, 0, len(values))
	for _, value := range values {
		if value != "" {
			result = append(result, value)
		}
	}
	return result
}

func mapBoolToFlag(enabled bool, flag string) string {
	if enabled {
		return flag
	}
	return ""
}

func renderStringFlag(name string, value string) string {
	if value == "" {
		return ""
	}
	return name + " " + quoteShellValue(value)
}

func quoteShellValue(value string) string {
	if value == "" {
		return `""`
	}
	if strings.ContainsAny(value, " ,:\t") {
		return fmt.Sprintf("%q", value)
	}
	return value
}

func runDispatchWizard(cmd *cobra.Command) (dispatchpkg.Options, error) {
	choices, err := discoverDispatchWizardChoices(cmd.Context())
	if err != nil {
		return dispatchpkg.Options{}, err
	}

	state := newDispatchWizardState()
	if len(choices.repoOptions) > 0 {
		state.selectedRepos = []string{choices.repoOptions[0].Value}
	}
	if len(choices.orgOptions) > 0 {
		state.selectedOrg = choices.orgOptions[0].Value
	}

	currentBranch := func() (string, error) {
		return GetCurrentBranch(cmd.Context())
	}
	if branch, branchErr := currentBranch(); branchErr == nil {
		state.applyCurrentBranchDefault(branch)
	}

	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Dispatch mode").
				Options(
					huh.NewOption("Local", dispatchWizardModeLocal),
					huh.NewOption("Server", dispatchWizardModeServer),
				).
				Value(&state.modeChoice),
		).Title("Mode").Description("Choose where the dispatch should run."),
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Scope").
				OptionsFunc(func() []huh.Option[string] {
					return choices.scopeOptions(state)
				}, &state).
				Value(&state.scopeType),
		).Title("Scope").Description("Choose which server-side scope to dispatch.").
			WithHideFunc(func() bool {
				return !state.showScopePicker(choices)
			}),
		huh.NewGroup(
			huh.NewMultiSelect[string]().
				Title("Repos").
				Description("Select repos to include.").
				Filterable(true).
				OptionsFunc(func() []huh.Option[string] {
					return append([]huh.Option[string](nil), choices.repoOptions...)
				}, nil).
				Value(&state.selectedRepos).
				Validate(func(value []string) error {
					if state.effectiveScopeType(choices) == dispatchWizardScopeSelectedRepos && len(value) == 0 {
						return errors.New("select at least one repo")
					}
					return nil
				}),
		).Title("Repos").Description("Choose which repos to include.").
			WithHideFunc(func() bool {
				return !state.showRepoPicker(choices)
			}),
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Organization").
				Description("Select the organization to dispatch.").
				OptionsFunc(func() []huh.Option[string] {
					if len(choices.orgOptions) == 0 {
						return []huh.Option[string]{huh.NewOption("No organizations discovered", "")}
					}
					return append([]huh.Option[string](nil), choices.orgOptions...)
				}, nil).
