    webhooks: z.object({
      github: z.string(),
      health: z.string(),
    }),
    runners: z.object({
      list: z.string(),
      detail: z.string(),
      trigger: z.string(),
      cancel: z.string(),
      update_settings: z.string(),
    }),
    trails: z.object({
      list: z.string(),
      create: z.string(),
      detail: z.string(),
      update: z.string(),
      delete: z.string(),
      add_comment: z.string(),
      edit_comment: z.string(),
      delete_comment: z.string(),
      submit_review: z.string(),
      get_reviews: z.string(),
      get_files: z.string(),
    }),
    runs: z.object({
      create: z.string(),
      list: z.string(),
      detail: z.string(),
      prompt: z.string(),
      stream: z.string(),
      destroy: z.string(),
      snapshots: z.string(),
      snapshot_detail: z.string(),
      snapshot_delete: z.string(),
    }),
  }),
})

