function buildDispatchGenerationUserPrompt(detail: DispatchDetail): string {
  const payload = {
    title: detail.title,
    covered_repos: detail.covered_repos,
    branches: detail.branches,
    voice: detail.voice ?? "neutral",
    window: detail.window,
    repos: detail.repos,
  }

  return `Voice preference:
<voice_preference>
${escapeDispatchPrompt(detail.voice?.trim() || "neutral")}
</voice_preference>

Structured dispatch data:
<dispatch_data>
${escapeDispatchPrompt(JSON.stringify(payload, null, 2))}
</dispatch_data>

Write the final dispatch in markdown.`
}

function getDispatchAnthropicKey(env: Env): string | undefined {
  return env.ANTHROPIC_API_KEY_DISPATCHES ?? env.ANTHROPIC_API_KEY
}

function getDispatchRateLimiter(env: Env): AnthropicRateLimiterStub | undefined {
  const ns = env.ANTHROPIC_RATE_LIMITER
  if (!ns) return undefined
  return ns.get(ns.idFromName("global"))
}

async function generateDispatchMarkdown(env: Env, detail: DispatchDetail): Promise<string> {
  const apiKey = getDispatchAnthropicKey(env)
  if (!apiKey) {
    throw new Error("ANTHROPIC_API_KEY_DISPATCHES is not configured")
  }

  const rateLimiter = getDispatchRateLimiter(env)
  if (rateLimiter) {
    const admission = await rateLimiter.reserve({
      estimatedTokens: DISPATCH_ANTHROPIC_TOKEN_ESTIMATE,
      estimatedRequests: 1,
    })
    if (!admission.granted) {
      throw new RateLimitedError(admission.waitMs)
    }
  }

  const response = await getAnthropicClient(apiKey).messages.create({
    model: DISPATCH_GENERATION_MODEL,
    max_tokens: 1400,
    system: DISPATCH_GENERATION_SYSTEM_PROMPT,
    messages: [{ role: "user", content: buildDispatchGenerationUserPrompt(detail) }],
  })

  const textBlock = response.content.find((block) => block.type === "text")
  if (!textBlock || textBlock.type !== "text") {
    throw new Error("No text returned for dispatch generation")
  }

  return textBlock.text.trim()
}

